const INF: i32 = 1 << 29;

fn calc(n: &[char], pat: &[char]) -> i32 {
    let len = n.len();
    let mut mi = INF;
    for i in 0 .. len {
        if n[i] == '0' { continue; }
        for j in 0 .. len {
            if i == j || pat[0] != n[j] { continue; }
            for k in 0 .. len {
                if i == k || j == k || pat[1] != n[k] { continue; }
                let mut cost = 0;
                cost += i as i32;
                let mut x = if i < j { j } else { j + 1 } as i32;
                let mut y = if i < k { k } else { k + 1 } as i32;
                cost += (y - len as i32 + 1).abs();
                if x > y { x -= 1; }
                cost += (x - len as i32 + 2).abs();
                mi = min(mi, cost);
            }
        }
    }
    return mi;
}


