fn main() {
    "abc".split_whitespace();
    let mut input = String::new();
    io::stdin().read_line(&mut input);
    let mut iter = input.split_whitespace();
    let distance: i64 = iter.next().expect("distance expected").parse().expect("integer distance expected");
    let km_per_stop: i64 = iter.next().expect("km_per_stop expected").parse().expect("integer km_per_stop expected");
    let car_km_time: i64 = iter.next().expect("car_km_time expected").parse().expect("car_km_time distance expected");
    let walk_km_time: i64 = iter.next().expect("walk_km_time expected").parse().expect("walk_km_time distance expected");
    let repair_time: i64 = iter.next().expect("repair_time expected").parse().expect("repair_time distance expected");

    let trip_time;
    let car_cost : i64 = car_km_time * km_per_stop - walk_km_time * km_per_stop + repair_time;
    if car_cost >= 0 {
        let car_dist = cmp::min(km_per_stop, distance);
        let walk_dist = distance - car_dist;
        trip_time = car_dist * car_km_time + walk_dist * walk_km_time;
    } else {
        let full_stops = distance / km_per_stop;
        let distance_cost = (full_stops * km_per_stop) * car_km_time;
        let repair_cost = (full_stops - 1) * repair_time;
        let full_stops_cost = distance_cost + repair_cost;

        let remaining_dist = distance % km_per_stop;
        let remaining_walk = remaining_dist * walk_km_time;
        let remaining_car = remaining_dist * car_km_time + repair_time;
        let remaining_cost = cmp::min(remaining_walk, remaining_car);

        trip_time = full_stops_cost + remaining_cost;
    }
    println!("{}", trip_time);

}

