                        length += 1;
                        continue;
                    }
                    ans += total;
                    let mut t = total;
                    for num in &table {
                        t -= num;
                        ans += t;
                    }
                    if table[length - 1] != 0 {
                        table.push(0);
                        length += 1;
                    }
                }
                'A' => {
                    if length != 0 {
                        table[length - 1] += 1;
                        total += 1;
                    }
                }
                _ => (),
            }
        }

        println!("{}", ans);
        input.clear();
        table.clear();
        ans = 0;
        total = 0;
        length = 0;
    }

    Ok(())
}

