fn binexp(mut x: u64, mut y: u64) -> u64 {
    let mut res = 1;
    while y != 0 {
        if y & 1 == 1 {
            res *= x;
        }
        x*=x;
        y>>=1;
    }
    res
}

use std::io;

fn steps(dist: i32, counter: &mut i32) -> &i32 {
    match dist {
        dist if dist <= 0 => (),
        dist if dist % 5 == 0 => {
            *counter += 1;
            steps(dist - 5, counter);
        }
        dist if dist % 4 == 0 => {
            *counter += 1;
            steps(dist - 4, counter);
        }
        dist if dist % 3 == 0 => {
            *counter += 1;
            steps(dist - 3, counter);
        }
        dist if dist % 2 == 0 => {
            *counter += 1;
            steps(dist - 2, counter);
        }
        dist if dist % 1 == 0 => {
            *counter += 1;
            steps(dist - 1, counter);
        }
        _ => (),
    }
    counter
}

