fn resolver(value: usize, step: usize) -> usize {
    if value == 1 {
        step + 1
    } else if value % 5 == 0 {
        (value / 5) + step
    } else if value % 4 == 0 {
        (value / 4) + step
    } else if value % 3 == 0 {
        (value / 3) + step
    } else if value % 2 == 0 {
        (value / 2) + step
    } else {
        resolver(value - 5, step + 1)
    }
}

