fn is_square(n: u32) -> bool {
    let mut l: u64 = 1;
    let mut r: u64 = 60000;
    while r - l > 1 {
        let m = (r + l) / 2;
        if m * m > 0 && m * m <= n as u64 {
            l = m
        } else {
            r = m
        }
    }
    return l * l == n as u64;
}

fn recurse<F : FnMut(u32)>(n: u32, mut f: F) {
    if n < 10 {
        return; 
    }

    let mut pow10: u64 = 1;
    while (n as u64) >= pow10 {
        if pow10 * 10 > (n as u64) && ((n as u64) % pow10 < pow10 / 10) {
            continue
        }
        f(((n as u64 / (pow10 * 10) * pow10) + (n as u64 % pow10)) as u32);

        pow10 *= 10;
    }
}

fn get(n: u32, xs: &mut Vec<Option<Option<u32>>>) -> Option<u32> {
    if xs[n as usize].is_none() {
        if is_square(n) {
            xs[n as usize] = Some(Some(0));
        } else {
            let mut result: Option<u32> = None;
            recurse(n, |n_rm| {
                if let Some(k_rm) = get(n_rm, xs) {
                    result = result.map_or(
                        Some(k_rm + 1), |k| Some(cmp::min(k, k_rm + 1))
                    );
                }
            });
            xs[n as usize] = Some(result);
        }
    }
    return xs[n as usize].unwrap();
}

