use std::fmt::Debug;
use std::str::FromStr;

pub struct TokenReader {
    reader: std::io::Stdin,
    tokens: Vec<String>,
    index: usize,
}

impl TokenReader {
    pub fn new() -> Self {
        Self {
            reader: std::io::stdin(),
            tokens: Vec::new(),
            index: 0,
        }
    }

    pub fn next<T>(&mut self) -> T
    where
        T: FromStr,
        T::Err: Debug,
    {
        if self.index >= self.tokens.len() {
            self.load_next_line();
        }
        self.index += 1;
        self.tokens[self.index - 1].parse().unwrap()
    }

    pub fn vector<T>(&mut self) -> Vec<T>
    where
        T: FromStr,
        T::Err: Debug,
    {
        if self.index >= self.tokens.len() {
            self.load_next_line();
        }
        self.index = self.tokens.len();
        self.tokens.iter().map(|tok| tok.parse().unwrap()).collect()
    }

    pub fn load_next_line(&mut self) {
        let mut line = String::new();
        self.reader.read_line(&mut line).unwrap();

        self.tokens = line
            .split_whitespace()
            .map(String::from)
            .collect();
        self.index = 0;
    }
}

fn gcd(mut a: i32, mut b: i32) -> i32 {
    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }
    a
}

fn lcm(a: i32, b: i32) -> i32 {
    ((a as i64 * b as i64) / (gcd(a, b) as i64)) as i32
}

fn solve(n: i32) -> (i32, i32) {
    let mut res = (n / 2, n - n / 2);
    let mut res_lcm = lcm(res.0, res.1);

    let mut i = 1i64;
    while i * i <= n as i64 {
        if n % i as i32 != 0 {
            i += 1;
            continue;
        }

        let a = i as i32;
        let b = n - a;
        let curr_lcm = lcm(a, b);

        if curr_lcm < res_lcm && a > 0 && b > 0 {
            res_lcm = curr_lcm;
            res = (a, b);
        }

        let a = n / i as i32;
        let b = n - a;
        let curr_lcm = lcm(a, b);

        if curr_lcm < res_lcm && a > 0 && b > 0 {
            res_lcm = curr_lcm;
            res = (a, b);
        }
        i += 1;
    }
    res
}

fn main() {
    let mut reader = TokenReader::new();
    let tests = reader.next();

    for _ in 0..tests {
        let n = reader.next();
        let (a, b) = solve(n);
        println!("{} {}", a, b);
    }
}

