fn is_prime(n: i32) -> bool {
    if n < 2 {
        return false;
    }

    let mut i: i64 = 2;
    while i * i <= n as i64 {
        if n as i64 % i == 0 {
            return false;
        }
        i += 1;
    }
    true
}

fn solve(n: i32) -> (i32, i32) {
    if n % 2 == 0 {
        return (n / 2, n / 2);
    }
    if is_prime(n) {
        return (1, n - 1);
    }

    let mut res = (n / 2, n / 2 + 1);
    let mut res_lcm = lcm(res.0, res.1);

    for i in 1..=n/2 + 1 {
        let a = i;
        let b = n - i;
        let curr_lcm = lcm(a, b);

        if curr_lcm < res_lcm {
            res_lcm = curr_lcm;
            res = (a, b);
        }
    }
    res
}

