fn solve() {
    let (n, m) = parse_line!(usize, usize);
    let l = parse_line_to_vec!(usize);
    let mut result = vec![0; n];
    let mut ok = true;
    for i in 1..m {
        let leader = l[i - 1] - 1;
        let diff = (n + l[i] - l[i - 1]) % n;
        if result[leader] == 0 {
            result[leader] = diff;
        }else if result[leader] != diff {
            ok = false;
        }
    }
    for i in 0..n {
        if result[i] == 0 {
            continue;
        }
        let mut local = true;
        for j in 0..i {
            local &= result[i] != result[j];
        }
        ok &= local;
    }
    if !ok {
        return println!("-1");
    }
    let mut s = std::collections::HashSet::<usize>::new();
    s.extend(result.iter());
    let mut next = 1;
    for i in 0..n {
        if result[i] != 0 {
            continue;
        }
        while s.contains(&next) {
            next += 1;
        }
        result[i] = next;
        next += 1;
    }
    for x in result {
        print!("{} ", x);
    }
    println!();
}

