        m: usize,
        k: usize,
        c: i64,
        d: i64,
        a: [usize1; k],
        e: [(usize1, usize1); m],
    }
    let w = 101;
    let size = n * w + 2;
    let mut graph = Graph::new(size);
    let src = size - 1;
    let dst = src - 1;
    let pos = |a: usize, b: usize| -> usize {
        assert!(a < 101 && b < n);
        a * n + b
    };
    for a in a {
        graph.add_edge(src, pos(0, a), 1, 0);
    }
    for i in 0..w {
        graph.add_edge(pos(i, 0), dst, 50, c * i as i64);
    }
    for (a, b) in e {
        for i in 1..w {
            for j in 1..=n {
                let x = j as i64;
                graph.add_edge(pos(i - 1, a), pos(i, b), 1, d * (2 * x - 1));
                graph.add_edge(pos(i - 1, b), pos(i, a), 1, d * (2 * x - 1));
            }
        }
    }
    for i in 1..w {
        for j in 0..n {
            graph.add_edge(pos(i - 1, j), pos(i, j), 50, 0);
        }
    }
