use std::cmp::{ min, max };

type Point = (i128, i128);

fn intersect(a: &Point, b: &Point, c: &Point, d: &Point) -> (Point, Point) {
    let l = max(min(a.0, b.0), min(c.0, d.0));
    let r = min(max(a.0, b.0), max(c.0, d.0));
    let u = min(max(a.1, b.1), max(c.1, d.1));
    let d = max(min(a.1, b.1), min(c.1, d.1));
    if l >= r || u <= d {
        ((0,0), (0,0))
    } else {
        ((l, d), (r, u))
    }
}

fn area(x: &Point, y: &Point) -> i128 {
    (x.0 - y.0).abs() * (x.1 - y.1).abs()
}

fn main() {
    let mut scan = Scanner::default();
    let (p1, p2): (Point, Point) = ((scan.next::<i128>(), scan.next::<i128>()),(scan.next::<i128>(), scan.next::<i128>()));
    let (p3, p4): (Point, Point) = ((scan.next::<i128>(), scan.next::<i128>()),(scan.next::<i128>(), scan.next::<i128>()));
    let (p5, p6): (Point, Point) = ((scan.next::<i128>(), scan.next::<i128>()),(scan.next::<i128>(), scan.next::<i128>()));
    let wb1 = intersect(&p1, &p2, &p3, &p4);
    let wb2 = intersect(&p1, &p2, &p5, &p6);
    let sb1b2 = intersect(&wb1.0, &wb1.1, &wb2.0, &wb2.1);
    let a = area(&p1, &p2);
    let b = area(&wb1.0, &wb1.0);
    let c = area(&wb2.0, &wb2.0);
    let d = area(&sb1b2.0, &sb1b2.0);
    println!("{}", if a > b + c -d { "YES" } else { "NO" });
}

