fn tryv(nn: u64, k: u64) -> bool {
    // println!("n: {}, k: {}", nn, k);
    // println!("=====================");
    if k == 0 { return false; }
    let mut n = nn;
    let mut v: u64 = 0;
    loop {
        if v >= nn/2 {
            return true;
        } else if v + n < nn/2 {
            return false;
        }

        if k >= n {
            v += n;
            n = 0;
        } else {
            v += k;
            n -= k;
        }

        n -= n/10;
        // println!("left: {}, vasya: {}", n, v);
    }
}

