fn solve(n: i32, a: i32, x: i32, b: i32, y: i32) -> bool {
    let x = if x < a { x + n } else { x };
    let y = if y > b { y - n } else { y };
    (y .. b + 1).rev().zip(a .. x + 1).any(|(i, j)| i % n == j % n)
}

