fn main() {
	let mut rin = reader();
	let mut rout = writer();

	l!(r,g = rin.u());
	let mut dp = vec![ (r,g,Z::new(1)) ];
	let mut sum = dp[0].2;
	let mut sol = sum;
	for n in 1.. {
		if dp.len() == 0 {
			break;
		}
		sol = sum;
		let mut dp1 = Vec::new();
		for (r,g,v) in dp.drain(..) {
			if r >= n {
				dp1.push( (r-n,g,v) );
			}
			if g >= n {
				dp1.push( (r,g-n,v) );
			}
		}
		dp1.sort();
		let mut last_r = r+1;
		sum = Z::new(0);
		for (r,g,v) in dp1 {
			sum += v;
			if r == last_r {
				dp.last_mut().unwrap().2 += v;
			} else {
				last_r = r;
				dp.push( (r,g,v) );
			}
		}
	}
