fn find_min(m: usize, s: usize) -> String {
    let mut num = vec![0; m];
    num[0] = 1;
    let mut i = m - 1;
    let mut sum = 1;

    while sum + 9 < s {
        num[i] = 9;
        i -= 1;
        sum += 9;
    }

    num[i] += (s - sum) as u8;
    vec_to_num(&num)
}

fn find_max(m: usize, s: usize) -> String {
    let mut num = vec![9; m];
    let mut i = m - 1;
    let mut sum = 9 * m;

    while sum - 9 > s {
        num[i] = 0;
        i -= 1;
        sum -= 9;
    }

    num[i] -= (sum - s) as u8;
    vec_to_num(&num)
}

fn vec_to_num(v: &Vec<u8>) -> String {
    v.into_iter()
        .map(|digit| (digit + 48) as char)
        .collect::<String>()
}

