fn get_max_digits(length: usize, sum: u32) -> Option<Vec<u32>> {
    if length == 0 {
        return None;
    }
    if (sum == 0) && (length > 1) {
        return None;
    }
    if sum == 0 {
        return Some(vec![0]);
    }
    let mut result: Vec<u32> = Vec::with_capacity(length);
    let mut rest_sum: u32 = sum;
    let first_digit: u32;
    if rest_sum > 9 {
        first_digit = 9;
    } else {
        first_digit = rest_sum;
    }
    result.push(first_digit);
    rest_sum -= first_digit;

    for _ in 1..length {
        let digit: u32;
        if rest_sum > 9 {
            digit = 9;
        } else {
            digit = rest_sum;
        }
        result.push(digit);
        rest_sum -= digit;
    }

    if rest_sum == 0 {
        return Some(result);
    } else {
        return None;
    }
}

fn get_min_digits(length: usize, sum: u32) -> Option<Vec<u32>> {
    if (sum == 0) && (length > 1) {
        return None;
    }
    if sum == 0 {
        return Some(vec![0]);
    }
    let mut result: Vec<u32> = Vec::with_capacity(length);
    let mut rest_sum: u32 = sum - 1;

    for _ in 1..length {
        let digit: u32;
        if rest_sum > 9 {
            digit = 9;
        } else {
            digit = rest_sum;
        }
        result.push(digit);
        rest_sum -= digit;
    }

    if rest_sum >= 9 {
        return None;
    }

    let last_digit: u32 = rest_sum + 1;
    result.push(last_digit);

    result.reverse();
    return Some(result);
}

