fn count_ways(n: usize) -> usize {
    let mut dynamic = vec![vec![0; 4]; n + 1];
    dynamic[1] = vec![1usize; 4];
    *dynamic[1].last_mut().unwrap() = 0;

    for step_count in 2..=n {
        for vertex_id in 0..=3 {
            for neighbor_id in (0..=3).filter(|&x| x != vertex_id) {
                dynamic[step_count][vertex_id] += dynamic[step_count - 1][neighbor_id];
            }
            dynamic[step_count] %= 1000000007;
        }
    }
    *dynamic.last().unwrap().last().unwrap()
}


