struct Scan {
    buffer: std::collections::VecDeque<String>
}

impl Scan {
    fn new() -> Scan {
        Scan { buffer: std::collections::VecDeque::new() }
    }

    fn next<T: std::str::FromStr>(&mut self)-> T {
        loop {
            if let Some(token) = self.buffer.pop_front() {
                break token.parse::<T>().ok().unwrap();
            }
            let mut line = String::new();
            std::io::stdin().read_line(&mut line).expect("Fail to read");
            self.buffer = line.split_whitespace().map(String::from).collect();
        }
    }

}

fn dfs_moves(acc: usize, current: usize, goal: usize, visited: &mut [bool;20000]) -> usize {
    if visited[current] { return std::usize::MAX; }
    visited[current] = true;
    if current >= goal {
        return acc + current - goal;
    }
    let mut result = dfs_moves(acc + 1, current*2, goal, visited);
    if current > 1 {
        let decr_move = dfs_moves(acc + 1, current-1, goal, visited); 
        result = result.min(decr_move);
    }
    result
}

