    let mut scan = Scan::new();
    let n: usize = scan.next();
    let m: usize = scan.next();
    if m<= n {
        println!("{}", n - m);
        return;
    }
    let mut seen = [false; 20000];
    let result = dfs_moves(0, n, m, &mut seen);
    println!("{}", result);
}

