fn bfs(n: i32, m: i32) -> i32 {
    let mut q = std::collections::VecDeque::new();

    q.push_back((n, 0));
    while !q.is_empty() {
        let x = q.pop_front().unwrap();
        if x.0 == m {
            return x.1;
        }
        if x.0 < 0 {
            continue;
        }
        q.push_back((x.0 - 1, x.1 + 1));
        q.push_back((x.0 * 2, x.1 + 1));
    }

    1
}

