fn count_max_sequence_length(input_str: String) -> u16 {
    let bytes = input_str.as_bytes();
    let mut max_sequence_length = 1;
    let mut current_sequence_length = 1;
    for i in 1..input_str.len() {
        if bytes[i - 1] == bytes[i] {
            current_sequence_length += 1
        } else {
            max_sequence_length = max(max_sequence_length, current_sequence_length);
            current_sequence_length = 1
        }
    }
    return max_sequence_length;
}

