use std::io::stdin;
use std::cmp::min;

fn main() {
    let mut input_line = String::new();
    stdin().read_line(&mut input_line);

    let input_iter = input_line.
        split_whitespace().
        map(|x| x.parse::<usize>().unwrap());

    let input: Vec<_> = input_iter.collect();

    let owned = input[0];
    if owned % 4 == 0 {
        // Already meet criteria
        println!("0");
        return;
    }

    let purchase = 4 - owned % 4;

    let mut dp = vec![usize::max_value(); 9];
    dp[0] = 0;

    for i in 0..9 {
        for j in 1..4 {
            if i >= j {
                dp[i] = min(dp[i - j] + input[j], dp[i]);
            }
        }
    }

    println!("{}", min(dp[purchase], dp[purchase + 4]));
}

