#[allow(dead_code)]
struct Scanner {
    stdin: Stdin,
    id: usize,
    buf: Vec<u8>,
}

#[allow(dead_code)]
impl Scanner {
    fn new() -> Scanner {
        Scanner {
            stdin: io::stdin(),
            id: 0,
            buf: Vec::new(),
        }
    }
    fn next_line(&mut self) -> Option<String> {
        let mut res = String::new();
        match self.stdin.read_line(&mut res) {
            Ok(0) => return None,
            Ok(_) => Some(res),
            Err(why) => panic!("error in read_line: {}", why.description()),
        }
    }
    fn next<T: FromStr>(&mut self) -> Option<T> {
        while self.buf.len() == 0 {
            self.buf = match self.next_line() {
                Some(r) => {
                    self.id = 0;
                    r.trim().as_bytes().to_owned()
                }
                None => return None,
            };
        }
        let l = self.id;
        assert!(self.buf[l] != b' ');
        let n = self.buf.len();
        let mut r = l;
        while r < n && self.buf[r] != b' ' {
            r += 1;
        }
        let res = match str::from_utf8(&self.buf[l..r]).ok().unwrap().parse::<T>() {
            Ok(s) => Some(s),
            Err(_) => panic!("parse error"),
        };
        while r < n && self.buf[r] == b' ' {
            r += 1;
        }
        if r == n {
            self.buf.clear();
        } else {
            self.id = r;
        }
        res
    }
    fn ne<T: FromStr>(&mut self) -> T {
        self.next::<T>().unwrap()
    }
}

macro_rules! scanln {
    () => ({
        let mut buffer = String::new();
        ::std::io::stdin().read_line(&mut buffer).expect("Unable to read line");
        buffer
    });
    ($($t: ty),+) => ({
        scanln!($($t),+, |c: char| c.is_whitespace())
    });
    ($($t: ty),+, $sp: expr) => ({
        let mut buffer = scanln!();
        let mut iter = buffer.split($sp);
        ($(iter.next().unwrap().parse::<$t>().expect("Unable to parse token")),+)
    });
}

fn main() {
    const MOD: u64 = 1000000009;
    let mut dp = vec![[[[[0u64; 2]; 32]; 32]; 32]; 1001].into_boxed_slice();
    let (n, h) = scanln!(usize, usize);
    dp[0][0][0][0][0] = 1;

    for i in 1..=n {
        for a in 0..=(h + 1) {
            for b in a..=(h + 1) {
                for c in b..=(h + 1) {
                    for y in 0..2 {
                        let val = dp[(i - 1) as usize][a][b][c][y];
                        let ta = if a + 1 > h { h + 1 } else { a + 1 };
                        let tb = if b + 1 > h { h + 1 } else { b + 1 };
                        let tc = if c + 1 > h { h + 1 } else { c + 1 };
                        dp[i][ta][tb][tc][y] += val;
                        if y == 0 {
                            dp[i][1][tb][tc][(ta > h) as usize] += val;
                            dp[i][1][ta][tc][(tb > h) as usize] += val;
                            dp[i][1][ta][tb][(tc > h) as usize] += val;
                        } else {
                            dp[i][tb][tc][h + 1][(ta > h) as usize] += val;
                            dp[i][ta][tc][h + 1][(tb > h) as usize] += val;
                            dp[i][ta][tb][h + 1][(tc > h) as usize] += val;
                        }
                    }
                }
            }
        }
    }

    let mut res = 0;

    for a in 0..=(h + 1) {
        for b in a..=(h + 1) {
            for c in b..=(h + 1) {
                for y in 0..2 {
                    if (a < h) || (b < h) || (c < h) || (y == 0) {
                        res += dp[n][a][b][c][y];
                    }
                }
            }
        }
    }

    println!("{}", res % MOD);
}

