type BoxResult<T> = Result<T, Box<std::error::Error>>;

fn main() {
    let mut scanner = Scanner::new(stdin());
    let s = scanner.read_chars().unwrap();
    let t = scanner.read_chars().unwrap();
    let mut maximum = 0;
    for i in 0..(s.len() - 1) {
        for j in i..s.len() {
            if judge(&s, &t, i, j) {
                maximum = max(j - i + 1, maximum);
            }
        }
    }
    println!("{}", maximum);
}

fn judge(s: &[char], t: &[char], start: usize, end: usize) -> bool {
    let mut index = 0;
    for i in 0..s.len() {
        if i >= start && i <= end {
            continue;
        }
        if s[i] == t[index] {
            index += 1;
        }
        if index == t.len() {
            break;
        }
    }
    index == t.len()
}

