fn distance(a: &(u8, u8), b: &(u8, u8)) -> u8 {
    let ax = a.0 as i64;
    let ay = a.1 as i64;
    let bx = b.0 as i64;
    let by = b.1 as i64;

    let diffx = if 0 < (bx - ax) { bx - ax } else { ax - bx };
    let diffy = if 0 < (by - ay) { by - ay } else { ay - by };

