        g = (g * x + y) % z;
    }
    let mut b = vec![0u32; h * (w - c + 1)];
    let op = |a: &u32, b: &u32| std::cmp::min(*a, *b);
    let mut q = FoldableDeque::new(op);
    for (i, a) in a.chunks(w).enumerate() {
        for a in a.iter().take(c - 1) {
            q.push_back(*a);
        }
        for (b, a) in b[i..].iter_mut().step_by(w - c + 1).zip(a.iter().skip(c - 1)) {
            q.push_back(*a);
            *b = q.find().unwrap();
            q.pop_front();
        }
    }
    let mut ans = 0u64;
    for b in b.chunks(h) {
        q.clear();
        for b in b.iter().take(r - 1) {
