    let l = ['c', 'o', 'd', 'e', 'f', 'o', 'r', 'c', 'e', 's'];
    let mut v = vec![1usize; 10];
    let mut max_comb = 1;
    let mut selection = 0;
    let n: usize = r.read()[0];

    while max_comb <= n {
        for i in 0..v.len() {
            let comb = compute(&v, i);
            if comb > max_comb {
                selection = i;
                max_comb = comb;
            }
        }
        v[selection] += 1;
    }

    for i in 0..v.len() {
        for _ in 0..v[i] {
            w.push(l[i]);
        }
    }
    w.push('\n');

    w.write();
}

fn compute(v: &Vec<usize>, i: usize) -> usize {
    let mut comb = 1;
    for j in 0..v.len() {
        comb *= if j == i { v[j] + 1 } else { v[j] }
    }

    comb
}

