use std::cmp::*;

fn run() {
    input! {
        n: usize,
        p: [(chars, i32, i32); n],
    }
    let p = p
        .into_iter()
        .map(|p| ((p.0[0] == 'B') as usize, p.1, p.2))
        .collect::<Vec<_>>();
    let mut sum = vec![([0, 0], 0, 0)];
    for &(x, y, z) in p.iter() {
        for i in 0..sum.len() {
            let (mut a, mut b, mut c) = sum[i];
            a[x] += 1;
            b += y;
            c += z;
            sum.push((a, b, c));
        }
    }
    let inf = std::i32::MAX / 2;
    let mut now = vec![(0, 0, 0, 0)];// bit, Rのヒット、Bのヒット、最小値
    for _ in 0..n {
        let mut next = std::collections::BTreeMap::new();
        for (bit, x, y, v) in now {
//            println!("{} {} {} {}", bit, x, y, v);
            let rem_a = v - sum[bit].1 + x;
            let rem_b = v - sum[bit].2 + y;
            for (i, &(_, a, b)) in p.iter().enumerate() {
                if bit >> i & 1 == 1 {
                    continue;
                }
                let mut x = x;
                let mut y = y;
                let mut add = 0;
                let mut p = max(0, a - rem_a);
                if p > 0 {
                    x += std::cmp::min(p, sum[bit].0[0]);
                    p -= sum[bit].0[0];
                }
                add = max(add, p);
                let mut p = max(0, b - rem_b);
                if p > 0 {
                    y += std::cmp::min(p, sum[bit].0[1]);
                    p -= sum[bit].0[1];
                }
                add = max(add, p);
                let v = v + add;
                let po = next.entry((bit | (1 << i), x, y)).or_insert(v);
                *po = std::cmp::min(*po, v);
            }
        }
        let mut a = vec![];
        for ((bit, x, y), v) in next {
            a.push((bit, x, y, v));
        }
        now = a;
    }
    let ans = now.into_iter().map(|p| p.3).min().unwrap() + n as i32;
    println!("{}", ans);
}

fn main() {
    run();
}

