// ---------- begin chmin, chmax ----------
trait ChangeMinMax {
    fn chmin(&mut self, x: Self) -> bool;
    fn chmax(&mut self, x: Self) -> bool;
}

impl<T: PartialOrd> ChangeMinMax for T {
    fn chmin(&mut self, x: Self) -> bool {
        if *self > x {
            *self = x;
            true
        } else {
            false
        }
    }
    fn chmax(&mut self, x: Self) -> bool {
        if *self < x {
            *self = x;
            true
        } else {
            false
        }
    }
}
// ---------- end chmin, chmax ----------

use std::cmp::*;

fn run() {
    input! {
        n: usize,
        p: [(chars, i32, i32); n],
    }
    let mut p = p
        .into_iter()
        .map(|p| ((p.0[0] == 'B') as usize, p.1, p.2))
        .collect::<Vec<_>>();
    let mut add = 0;
    for p in p.iter_mut() {
        let n = n as i32;
        let mut v = 0;
        v.chmax(p.1 - n);
        v.chmax(p.2 - n);
        add += v;
        p.1.chmin(n);
        p.2.chmin(n);
    }
    let mut sum = vec![[0i32; 2]];
    for &(x, _, _) in p.iter() {
        for i in 0..sum.len() {
            let mut a = sum[i];
            a[x] += 1;
            sum.push(a);
        }
    }
    let inf = std::i32::MAX / 2;
    let mut dp_a = std::collections::BTreeMap::new();
    let mut dp_b = std::collections::BTreeMap::new();
    dp_a.insert((0, 0), 0);
    dp_b.insert((0, 0), 0);
    for _ in 0..n {
        let mut next_a = std::collections::BTreeMap::new();
        let mut next_b = std::collections::BTreeMap::new();
        for ((bit, rem), v) in dp_a {
            let sum = sum[bit];
            for (i, &(_, a, b)) in p.iter().enumerate() {
                if bit >> i & 1 == 1 {
                    continue;
                }
                let k = bit | (1 << i);
                let a = max(0, a - sum[0]);
                let b = max(0, b - sum[1]);
                if rem + b >= a {
                    let x = rem + b - a;
                    let po = next_a.entry((k, x)).or_insert(inf);
                    po.chmin(v + b);
                } else {
                    let x = a - (rem + b);
                    let po = next_b.entry((k, x)).or_insert(inf);
                    po.chmin(v + b + x);
                }
            }
        }
        for ((bit, rem), v) in dp_b {
            let sum = sum[bit];
            for (i, &(_, a, b)) in p.iter().enumerate() {
                if bit >> i & 1 == 1 {
                    continue;
                }
                let k = bit | (1 << i);
                let a = max(0, a - sum[0]);
                let b = max(0, b - sum[1]);
                if rem + a >= b {
                    let x = rem + a - b;
                    let po = next_b.entry((k, x)).or_insert(inf);
                    po.chmin(v + a);
                } else {
                    let x = b - (rem + a);
                    let po = next_a.entry((k, x)).or_insert(inf);
                    po.chmin(v + a + x);
                }
            }
        }
        dp_a = next_a;
        dp_b = next_b;
    }
    let ans = add + dp_a.values().chain(dp_b.values()).cloned().min().unwrap() + n as i32;
    println!("{}", ans);
}

fn main() {
    run();
}

