use std::io::{self, Read};
use std::collections::HashMap;

struct Node {
    white: bool,
    black: bool,
    left: bool,
    right: bool,
    count: u32,
}

fn update_tree(tree: &mut Vec<Node>, index: usize, l: usize, r: usize, left: usize, right: usize) {
    let mid :usize = (l + r) / 2;
    if tree[index].black && !tree[index].white {
        return;
    }
    if l == left && r == right {
        tree[index].black = true;
        tree[index].white = false;
        tree[index].left = true;
        tree[index].right = true;
        tree[index].count = 1;
        return;
    } else if mid >= right {
        update_tree(tree, index * 2 + 1, l, mid, left, right);
    } else if mid + 1 <= left {
        update_tree(tree, index * 2 + 2, mid + 1, r, left, right);
    } else {
        update_tree(tree, index * 2 + 1, l, mid, left, mid);
        update_tree(tree, index * 2 + 2, mid + 1, r, mid + 1, right);
    }
    tree[index].white = tree[index * 2 + 1].white & tree[index * 2 + 2].white;
    tree[index].black = tree[index * 2 + 1].black & tree[index * 2 + 2].black;
    tree[index].left = tree[index * 2 + 1].left;
    tree[index].right = tree[index * 2 + 2].right;
    if tree[index * 2 + 1].right && tree[index * 2 + 2].left {
        tree[index].count = tree[index * 2 + 1].count + tree[index * 2 + 2].count - 1;
    } else {
        tree[index].count = tree[index * 2 + 1].count + tree[index * 2 + 2].count;
    }
    return;
}

fn main() {
