fn main() -> Result<(), Box<std::error::Error>> {
    let line = read_line()?;
    let mut nums = line
        .split(' ')
        .map(|s| s.parse::<i32>().unwrap());

    let _ = nums.next().unwrap();
    let mut b = nums.next().unwrap();

    let line = read_line()?;

    let nums = line
        .split(' ')
        .map(|s| s.parse::<i32>().unwrap())
        .collect::<Vec<_>>();

    let evency = nums
        .iter()
        .map(|n| if n % 2 == 0 { 1 } else { -1 })
        .collect::<Vec<_>>();

    let mut split_points = HashSet::new();
    let mut s = 0;

    for (i, e) in evency[..evency.len() - 1].iter().enumerate() {
        s += e;

        // println!("{}, {}, {}", i, s, e);

        if s == 0 {
            split_points.insert(i);
        }
    }

    let mut diffs = nums
        .iter()
        .zip(&nums[1..])
        .map(|(&prev, &curr)| (curr - prev).abs())
        .enumerate()
        .collect::<Vec<_>>();

    diffs.sort_unstable_by_key(|&(_, diff)| diff);

    println!("diffs: {:?}", diffs);
    println!("split_points: {:?}", split_points);

    let mut ans = 0;

    for (i, diff) in diffs {
        if split_points.contains(&i) && b >= diff {
            println!("split at {}, price {}, current budget: {}", i, diff, b);

            ans += 1;
            b -= diff;
        }
    }


    println!("{}", ans);

    Ok(())
}

