            self.dfs(v);
        }
    }
}

fn binary_search(a: &Vec<i64>) -> usize {
    let mut left = -1;
    let mut right = a.len() as i64;

    while right - left > 1 {
        let mid:usize = ((right+left)/2) as usize;
        //debug!(left,mid,right);
        if is_ok(mid) { right = mid as i64; }
        else { left = mid as i64; }
    }
    right as usize
}

