const PRIMES: [u128; 8] = [2, 3, 5, 7, 11, 13, 17, 19];
const WEIGHTS: [u128; 9] = [
    2 * 7 * 17,
    2 * 11,
    2 * 13 * 19,
    7 * 3,
    11 * 3 * 19 * 17,
    3 * 13,
    5 * 7 * 19,
