];

fn count_powers_of(x: u128, y: u128) -> u128 {
    let mut x = x;
    let mut n = 0;
    while x != 0 && x % y == 0 {
        n += 1;
        x /= y;
    }
    n
}

fn ix(c: char) -> usize {
    match c {
        'X' => 1,
        _ => 0,
    }
}

