    for (i, c) in board.chars().enumerate().filter(|p| p.1 != '.') {
        count[ix(c)] += 1;
        prod[ix(c)] *= WEIGHTS[i];
    }
    for i in 0..2 {
        for p in PRIMES.iter() {
            if count_powers_of(prod[i], *p) == 3 {
                wins[i] += 1;
            }
        }
    }
    if count[0] != count[1] && count[0] != count[1] - 1
        || wins[0] > 1
        || wins[1] > 1
        || wins[0] * wins[1] != 0
        || wins[0] == 1 && count[0] != count[1]
        || wins[1] == 1 && count[0] != count[1] - 1
