use std::io;
use std::io::Stdin;

const DIMENSION : usize = 3;
const NUM_SQUARES : usize = DIMENSION * DIMENSION;
const BLANK : u64 = 0;
const X : u64 = 1;
const O : u64 = 10;

fn read_line(stdin : &Stdin, line : &mut String) {
    match stdin.read_line(line) {
        Ok(_) => return,
        Err(msg) => panic!("Could not read line! Message: {}.", msg),
    }
}

fn read_board(stdin : &Stdin, board : &mut [[u64; DIMENSION]; DIMENSION]) {
    for i in 0 .. DIMENSION {
        let mut row = String::new();
        read_line(stdin, &mut row);
        let mut j = 0;
        for c in row.trim().chars() {
            if c == '.' {
                board[i][j] = BLANK;
            } else if c == 'X' {
                board[i][j] = X;
            } else if c == '0' {
                board[i][j] = O;
            } else {
                panic!("Unknown square on board: {}", c);
            }
            j = j + 1;
        }
    }
}

fn has_player_won(board: &[[u64; DIMENSION]; DIMENSION], player : u64) -> bool {
    let three_p = 3 * player;
    let row_0 = (board[0][0] + board[0][1] + board[0][2]) == three_p;
    let row_1 = (board[1][0] + board[1][1] + board[1][2]) == three_p;
    let row_2 = (board[2][0] + board[2][1] + board[2][2]) == three_p;
    let col_0 = (board[0][0] + board[1][0] + board[2][0]) == three_p;
    let col_1 = (board[0][1] + board[1][1] + board[2][1]) == three_p;
    let col_2 = (board[0][2] + board[1][2] + board[2][2]) == three_p;
    let dia_1 = (board[0][0] + board[1][1] + board[2][2]) == three_p;
    let dia_2 = (board[0][2] + board[1][1] + board[2][0]) == three_p;
    row_0 || row_1 || row_2 || col_0 || col_1 || col_2 || dia_1 || dia_2
}

fn has_first_player_won(board : &[[u64; DIMENSION]; DIMENSION]) -> bool {
    has_player_won(board, X)
}

fn has_second_player_won(board : &[[u64; DIMENSION]; DIMENSION]) -> bool {
    has_player_won(board, O)
}

fn print_board_state(board : &[[u64; DIMENSION]; DIMENSION]) {
    let mut num_x : i64 = 0;
    let mut num_o : i64 = 0;
    for i in 0 .. DIMENSION {
        for j in 0 .. DIMENSION {
            if board[i][j] == X {
                num_x = num_x + 1;
            } else if board[i][j] == O {
                num_o = num_o + 1;
            } else {
                // Do nothing ...
            }
        }
    }
    let sum = (num_x + num_o) as usize;
    let diff = num_x - num_o;
    let first_player_won = has_first_player_won(&board);
    let second_player_won = has_second_player_won(&board);
    if diff == 0 {
        if first_player_won {
            println!("illegal");
        } else if second_player_won {
            println!("the second player won");
        } else {
            if sum == NUM_SQUARES {
                println!("draw");
            } else {
                println!("first");
            }
        }
    } else if diff == 1 {
        if second_player_won {
            println!("illegal");
        } else if first_player_won {
            println!("the first player won");
        } else {
            println!("second");
        }
    } else {
        println!("illegal");
    }
}

fn main() {
    let stdin = io::stdin();
    let mut board = [[BLANK; DIMENSION]; DIMENSION];
    read_board(&stdin, &mut board);
    print_board_state(&board);
    // println!("{:?}", board);
}

