struct Scanner<R> {
    reader: R,
    buf_str: Vec<u8>,
    buf_iter: std::str::SplitAsciiWhitespace<'static>,
}

impl<R: std::io::BufRead> Scanner<R> {
    fn new(reader: R) -> Self {
        Self {
            reader,
            buf_str: Vec::new(),
            buf_iter: "".split_ascii_whitespace(),
        }
    }
    fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buf_iter.next() {
                return token.parse().ok().expect("Failed parse");
            }
            self.buf_str.clear();
            self.reader
                .read_until(b'\n', &mut self.buf_str)
                .expect("Failed read");
            self.buf_iter = unsafe {
                let slice = std::str::from_utf8_unchecked(&self.buf_str);
                std::mem::transmute(slice.split_ascii_whitespace())
            }
        }
    }
}

enum Answer {
    Illegal,
    First,
    Second,
    FirstWon,
    SecondWon,
    Draw,
}

fn solve(b: [[u8; 3]; 3]) -> Answer {
    let mut cnt1 = 0;
    let mut cnt2 = 0;
    for i in 0..3 {
        for j in 0..3 {
            if b[i][j] == 'X' as u8 {
                cnt1 += 1;
            } else if b[i][j] == '0' as u8 {
                cnt2 += 1;
            }
        }
    }

    if !(cnt1 == cnt2 || cnt1 == cnt2 + 1) {
        return Answer::Illegal;
    }

    let win_check = |p: u8| {
        for i in 0..3 {
            if b[i][0] == p && b[i][1] == p && b[i][2] == p {
                return true;
            }
            if b[0][i] == p && b[1][i] == p && b[2][i] == p {
                return true;
            }
        }
        return b[1][1] == p && ((b[0][0] == p && b[2][2] == p) || (b[0][2] == p && b[2][0] == p));
    };
    let first_won = win_check('X' as u8);
    let second_won = win_check('0' as u8);
    if first_won && second_won {
        return Answer::Illegal;
    }
    if first_won {
        return Answer::FirstWon;
    }
    if second_won {
        return Answer::SecondWon;
    }

    let mut is_finished = true;
    for i in 0..3 {
        for j in 0..3 {
            if b[i][j] == '.' as u8 {
                is_finished = false;
            }
        }
    }

    if is_finished {
        return Answer::Draw;
    }

    if cnt1 == cnt2 {
        Answer::First
    } else {
        Answer::Second
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let (stdin, stdout) = (std::io::stdin(), std::io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = std::io::BufWriter::new(stdout.lock());

    let mut a: Vec<String> = vec![];
    a.push(scan.next());
    a.push(scan.next());
    a.push(scan.next());

    let mut b: [[u8; 3]; 3] = [[0; 3]; 3];
    for i in 0..3 {
        b[i] = a[i].as_bytes().try_into().unwrap();
    }

    writeln!(
        out,
        "{}",
        match solve(b) {
            Answer::Illegal => "illegal",
            Answer::First => "first",
            Answer::Second => "second",
            Answer::FirstWon => "the first player won",
            Answer::SecondWon => "the second player won",
            Answer::Draw => "draw",
        }
    )?;

    Ok(())
}

struct Scan {
    buffer: std::collections::VecDeque<String>,
}

impl Scan {
    fn new() -> Scan {
        Scan {
            buffer: std::collections::VecDeque::new(),
        }
    }

    fn next_line(&self) -> String {
        let mut line = String::new();
        std::io::stdin().read_line(&mut line).expect("Fail to read");
        line
    }

    fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop_front() {
                break token.parse::<T>().ok().unwrap();
            }
            let line = self.next_line();
            self.buffer = line.split_whitespace().map(String::from).collect();
        }
    }
}

fn _main() {
    let mut scan = Scan::new();
    let mut r: u64 = scan.next();
    let mut g: u64 = scan.next();
    let mut b: u64 = scan.next();
    let mut result = r.min(g).min(b);
    r -= result;
    g -= result;
    b -= result;
    result += r / 3 + g / 3 + b / 3;
    println!("{}", result);
}

