fn reads<T: std::str::FromStr>(i: &mut StdinLock) -> Vec<T> {
    let mut s = String::new();
    i.by_ref().read_line(&mut s).ok();
    s.trim()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

fn main() {
    // initialize stdin
    let sin = std::io::stdin();
    let mut sin = sin.lock();
    let sin = &mut sin;

    let inputs: Vec<f64> = reads(sin);
    let m = inputs[0];
    let n = inputs[1];

    let case1 = (m / 2.).floor() as u64 * n as u64;
    let case2 = (n / 2.).floor() as u64 * m as u64;
    let mut other = 0;

    let ans = if case1 < case2 {
        other = m as u64;
        case2
    } else {
        other = n as u64;
        case1
    };

    if m as u64 % 2 == 0 && n as u64 % 2 == 0 {
        println!("{}", ans);
        return;
    }

    let remain = (other as f64 / 2.).floor() as u64;

    println!("{}", ans + remain);
}

