use std::cmp::{max, min};
use std::io::{Read, Write, stdin, stdout};

pub struct Scanner<U: Sized + Read> {
    pub buffer: Vec<String>,
    pub reader: U,
}
impl<U: Sized + Read> Scanner<U> {
    pub fn next<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            self.reader.read_to_string(&mut input).expect("Failed read");
            self.buffer = input.lines().rev().map(String::from).collect();
        }
    }

    pub fn new(reader: U) -> Self {
        return Scanner {
            buffer: vec![],
            reader,
        };
    }
}

// the maxium ways to cover a mxn rectangle using 1x2 bricks
pub fn get_cover_num(m: usize, n: usize) -> usize {
    let smaller = min(m, n);
    let bigger = max(m, n);
    if smaller == 0 {
        return 0;
    } else if smaller == 1 {
        return bigger / 2;
    } else if smaller == 2 {
        return bigger;
    }
    let q = smaller / 2;
    return q * bigger + bigger / 2;
}
pub fn solution_of_p50a(input: &mut Read, out: &mut Write) {
    let mut scanner = Scanner::new(input);
    let arr: Vec<usize> = scanner
        .next::<String>()
        .split(' ')
        .map(|e| {
            return e.parse::<usize>().unwrap();
        })
        .collect();
    let m = arr[0];
    let n = arr[1];

    let res = get_cover_num(m, n);
    writeln!(out, "{}\n", res).ok();
}

fn main() {
    solution_of_p50a(&mut stdin(), &mut stdout());
}

