}

macro_rules! read_vec {
    ($s: ident, $l: expr) => {
        {
            let mut v = Vec::with_capacity($l);
            for _ in 0..$l {
                v.push(to_str!(read!($s)));
            }
            v
        }
    };
    ($s: ident, $t: ty, $l: expr) => { // for ints
        {
            let mut v = Vec::with_capacity($l);
            for _ in 0..$l {
                v.push(read!($s, $t));
            }
            v
        }
    };
}

macro_rules! void {
    ($s: ident, $l: expr) => {
        if $l > 0 {
            let mut n = 0;
            let mut first = true;

            while n < $l {
                if $s.pos != 0 {
                    $s.stdin.consume($s.pos);
                }

                let buf = $s.stdin.fill_buf().unwrap();

                let mut resume = true;

                for (i, x) in buf.iter().enumerate() {
                    if x == &b' ' || x == &b'\n' {
                        if i == 0 && first {
                            continue;
                        }

                        n += 1;

                        if n == $l {
                            $s.pos = i+1;
                            resume = false;
                            break;
                        }
                    }
                }

                if resume {
                    $s.pos = buf.len();
                    first = false;
                }
            }
        }
    };
}

macro_rules! pipe {
    ($s: ident, $t: ty, $($x: ident),*) => {
        $(
            $x = read!($s, $t);
        )*
    };
    ($s: ident, $( ($x: ident, $t: ty) ),*) => {
        $(
            $x = read!($s, $t);
        )*
    };
    ($s: ident, $($x: ident),*) => {
        $(
            $x = read!($s);
        )*
    };
}

struct Reader<'a> {
    stdin: StdinLock<'a>,
    pos: usize,
    v_temp: Vec<u8>
}

impl<'a> Reader<'a> {
    fn new(stdin: StdinLock<'a>)/*'*/ -> Self {
        Reader {stdin, pos: 0, v_temp: vec![]}
    }

    fn read(&mut self) -> &[u8] {
        if self.pos != 0 {
            self.stdin.consume(self.pos);
        }
        let mut s = 0;
        let mut i = 0;

        let buf = self.stdin.fill_buf().unwrap();

        loop {
            if unsafe {buf.get_unchecked(i)} < &33 {
                if i > buf.len() {
                    let b_len = buf.len();
                    let mut idx_char = 0;

                    loop {
                        if unsafe {buf.get_unchecked(idx_char)} > &33 || idx_char == b_len {
                            break;
                        }
                        idx_char += 1;
                    }
                    let mut v1;
                    if b_len != idx_char {
                        v1 = vec![0; b_len-idx_char];
                        v1[..].copy_from_slice(&buf[idx_char..]);
                    } else {
                        v1 = vec![];
                    }

                    let new_buf = {
                        self.stdin.consume(b_len);
                        let buf = self.stdin.fill_buf().unwrap();
                        let mut i = 0;

                        loop {
                            if unsafe {buf.get_unchecked(i)} < &33 {
                                break if i == 0 {
                                    &[]
                                } else {
                                    &buf[..=i]
                                }
                            }
                            i += 1;
                        }
                    };
                    if !new_buf.is_empty() {
                        self.pos = new_buf.len();
                        v1.extend(new_buf.iter());
                    } else {
                        self.pos = 0;
                    }

                    self.v_temp = v1;

                    return &self.v_temp[..];
                } else if s == i {
                    s += 1;
                } else {
                    break;
                }
            }
            i += 1;
        }
        self.pos = i+1;

        if s == i {
            self.read()
        } else {
            &self.stdin.fill_buf().unwrap()[s..i]
        }
    }
}

fn main() {
    let stdin = stdin();
    let stdout = stdout();
    solve(&mut Reader::new(stdin.lock()), &mut BufWriter::new(stdout.lock()));
}

fn solve(r: &mut Reader, w: &mut BufWriter<StdoutLock>) {
    writeln!(w, "{}", (read!(r, u8)*read!(r, u8))>>1);
}

fn sieve_of_eratosthene(n: usize) -> Vec<bool> {
    let mut is_prime = vec![true; std::cmp::max(n, 2)];

    is_prime[0] = false;
    is_prime[1] = false;


    let mut i = 2;
    loop {
        while i < n && !is_prime[i] {
            i += 1;
        }

        let cur_prime = i;

        let mut q = 2;
        while q * cur_prime < n {
            is_prime[q * cur_prime] = false;
            q += 1;
        }

        i += 1;
        if i >= n {
            return is_prime;
        }
    }
}

fn primes(is_prime: &Vec<bool>) -> Vec<usize> {
    let mut primes = Vec::new();
    for i in 0..is_prime.len() {
        if is_prime[i] {
            primes.push(i);
        }
    }

    primes
}

fn is_number_good(prime: &Vec<usize>, n: usize) -> bool {
    let mut firstmultiplier = 0;

    for i in 0..prime.len() {
        if n % prime[i] == 0 {
            firstmultiplier = prime[i];
        }
    }

    for i in 0..prime.len() {
        if n % prime[i] == 0 && prime[i] != firstmultiplier {
            return true;
        }
    }

    false
}

fn main() {
    let mut str = String::new();

    std::io::stdin().read_line(&mut str).unwrap();

    let n = str.trim().parse::<usize>().unwrap();

    let is_prime = sieve_of_eratosthene(n);

    let mut c = 0;
    for i in 2..=n {
        if is_number_good(&primes(&is_prime), i) {
            c += 1;
        }
    }

    println!("{}", c);
}

