fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn lcm(a: u64, b: u64) -> u64 {
    if a == 0 || b == 0 {
        a + b
    } else {
        a / gcd(a, b) * b
    }
}

fn run() {
    input! {
        w: u64,
        c: [u64; 8],
    }
    let m = (1..=8).fold(0, |s, a| lcm(s, a));
    let mut ans = 0;
    let mut w = w;
    let mut c = c;
    for (i, c) in c.iter_mut().enumerate() {
        let k = (i + 1) as u64;
        let v = m / k;
        let q = *c / v;
        *c %= v;
        let d = std::cmp::min(w / m * m, q * v * k);
        ans += d;
        w -= d;
    }
    if w >= 8 * m {
        ans += c.iter().enumerate().fold(0, |s, (i, c)| s + (i + 1) as u64 * c);
    } else {
        let w = w as usize;
        let mut dp = vec![false; w + 1];
        dp[0] = true;
        for (i, &c) in c.iter().enumerate() {
            let k = i + 1;
            for _ in 0..c {
                for j in (k..=w).rev() {
                    dp[j] |= dp[j - k];
                }
            }
        }
        ans += dp.iter().rposition(|p| *p).unwrap() as u64;
    }
    println!("{}", ans);
}

fn main() {
    run();
}

macro_rules! parse_line {
    ($t: ty) => ({
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        let a_str = a_str.trim();
        a_str.parse::<$t>().expect("parse error")
    });
    ($($t: ty),+) => ({
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        let mut a_iter = a_str.split_whitespace();
        (
            $(
            a_iter.next().unwrap().parse::<$t>().expect("parse error"),
            )+
        )
    })
}

#[allow(unused_macros)]
macro_rules! parse_line_to_vec {
    ($t: ty) => {{
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        (a_str
            .split_whitespace()
            .map(|x| x.parse::<$t>().unwrap())
            .collect::<Vec<$t>>())
    }};
}

use std::io::Write;

fn solve(writer: &mut std::io::BufWriter<std::io::Stdout>) {
    let n = parse_line!(usize);
    let a = parse_line_to_vec!(u32);
    let mut dp = vec![vec![[n, n]; n + 1]; n + 1];
    dp[0][0][0] = 0;
    dp[0][0][1] = 0;
    for i in 0..n {
        if a[i] != 0 {
            if a[i] % 2 == 0 {
                for i in (1..=n).rev() {
                    for j in 0..=n {
                        dp[i][j][0] = std::cmp::min(dp[i][j][0],
                                    std::cmp::min(dp[i - 1][j][0], dp[i - 1][j][1] + 1));
                    }
                }
            }else{
                for i in 0..=n {
                    for j in (1..=n).rev() {
                        dp[i][j][1] = std::cmp::min(dp[i][j][1],
                                    std::cmp::min(dp[i][j - 1][1], dp[i][j - 1][0] + 1));
                    }
                }
            }
            continue;
        }
        for i in (0..=n).rev() {
            for j in (0..=n).rev() {
                if i > 0 {
                    dp[i][j][0] = std::cmp::min(dp[i][j][0],
                                std::cmp::min(dp[i - 1][j][0], dp[i - 1][j][1] + 1));
                }
                if j > 0 {
                    dp[i][j][1] = std::cmp::min(dp[i][j][0],
                                std::cmp::min(dp[i][j - 1][1], dp[i][j - 1][0] + 1));
                }
            }
        }
    }
    writeln!(writer, "{}", dp[n / 2][n - n / 2].iter().min().unwrap()).unwrap();
}

fn main() {
    let mut writer = std::io::BufWriter::new(std::io::stdout());
    let tests = 1; // parse_line!(usize);
    for _ in 0..tests {
        solve(&mut writer);
    }
}

