fn solve<Inner: BufRead, Output: Write>(inf: &mut Input<Inner>, ouf: &mut Output)
{
	let n = read!(inf,usize);
	let mut w = vec![0usize; 2 * n];
	for i in 0..2 * n {
		w[i] = read!(inf,usize);
	}
	w.sort();
	let mut ans = MOD;
	for i in 0..3 {
		let mut pos = i;
		let mut p = 0;
		while pos < 2 * n - 2 + i {
			p += w[pos + 1] - w[pos];
			pos += 2;
		}
		ans = min(ans, p);
	}
	writeln!(ouf, "{}", ans);
}

