fn can_be_splitted(slice : &[i32], sum : i32) -> bool {
    let mut curr_sum = 0;
    let mut index = 0;
    let mut at_least_one = false;
    loop {
        if index >= slice.len() {
            return at_least_one;
        }

        curr_sum += slice[index];
        if curr_sum == sum {
            curr_sum = 0;
            at_least_one = true;
        } else if curr_sum > sum {
            return false;
        }
        index += 1;
    }

    true
}

fn solve(length : usize, digits : Vec<i32>) -> (bool, i32) {
    let mut curr_sum = 0;
    for index in 0..(length - 1) {
        curr_sum += digits[index];
        if can_be_splitted(&digits[(index + 1)..], curr_sum) {
            return (true, curr_sum);
        }
