fn check_step(iter : &mut Iter<u64>, check_sum : u64) -> Option<bool> {
    if iter.as_slice().len() == 0 { return None }
    let mut sum = 0;
    while let Some(x) = iter.next() {
        sum += x;
        if sum == check_sum {
            return Some(true)
        }
    }
    Some(false)
}

fn check(mut iter : Iter<u64>, check_sum : u64) -> bool {
    if iter.as_slice().len() == 0 { return false }
    while let Some(flag) = check_step(&mut iter, check_sum) {
        if !flag { 
            return false 
        }
    }
    true
}

