use std::str::FromStr;
use std::io::Read;

struct Input {
  tokens: <std::vec::Vec<std::string::String> as IntoIterator>::IntoIter,
  read_all: bool,
}

impl Input {
  pub fn new(read_all: bool) -> Input {
    if read_all {
      let mut all = String::new();
      io::stdin().read_to_string(&mut all).unwrap();
      let tokens: Vec<String> = all.split_whitespace().map(|s| s.to_string()).collect();
      Input {
        tokens: tokens.into_iter(),
        read_all: true,
      }
    } else {
      Input {
        tokens: vec!().into_iter(),
        read_all: false,
      }
    }
  }

  fn refresh_next_line(&mut self) {
    if self.read_all {
      panic!();
    }
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).unwrap();
    let tokens: Vec<String> = buf.split_whitespace().map(|s| s.to_string()).collect();
    self.tokens = tokens.into_iter();
  }

  fn next_impl(&mut self) -> String {
    loop {
      if let Some(next) = self.tokens.next() {
        return next.to_string();
      }
      self.refresh_next_line();
    }
  }

  pub fn next<T: FromStr>(&mut self) -> T where <T as std::str::FromStr>::Err: std::fmt::Debug {
    let next_str = self.next_impl();
    next_str.parse().unwrap()
  }

  pub fn next_vec<T: FromStr>(&mut self, len: usize) -> Vec<T> where <T as std::str::FromStr>::Err: std::fmt::Debug {
    (0..len).map(|_i| self.next()).collect()
  }

  pub fn next_vec_read_len<T: FromStr>(&mut self) -> Vec<T> where <T as std::str::FromStr>::Err: std::fmt::Debug {
    let len = self.next();
    self.next_vec(len)
  }
}

