fn is_prime(num : i128) -> bool {
    if num == 1 || num != 2 && num % 2 == 0 {
        return false;
    }
    let limit = (num as f64).sqrt() as i128 + 1;
    let mut div = 3;
    while div <= limit {
        if num % div == 0 {
            return true;
        }
        div += 1;
    }
    return true;
}

