static MOD: i64 = 998244353;

fn pow(n: i64, x: i64) -> i64 {
    if x == 0 {
        return 1;
    }
    if n == 1 {
        return 1;
    }
    let h = pow(n, x / 2);
    let mut v = (h * h) % MOD;
    if x % 2 == 1 {
        v = (v * n) % MOD;
    }
    v
}

fn inv(x: i64) -> i64 {
    pow(x, MOD - 2)
}

