fn modpow(base: u32, expo: u32, modulo: u32) -> u32 {
    if expo == 0 {
        return 1;
    }
    let partial = modpow(base, expo / 2, modulo);
    let ans = (partial * partial) % modulo;
    if expo % 2 == 0 {
        ans
    }
    else {
        (ans * base) % modulo
    }
}

