fn gcd(mut a: i64, mut b: i64) -> i64 {
    while b > 0 {
        a %= b;
        let tmp = a;
        a = b;
        b = tmp;
    }
    a
}

fn lcm(a: i64, b: i64) -> i64 {
    a / gcd(a, b) * b
}

fn solution() {
    let mut scanner = Scanner::new();
    let n: i64 = scanner.next();
    let k: i64 = scanner.next();
    let a: i64 = scanner.next();
    let b: i64 = scanner.next();

    let mut x = std::i64::MAX;
    let mut y = 0;
    for s in [-a, a].iter() {
        for i in 0..n {
            let p = i * k;
            for s2 in [p - b, p + b].iter() {
                let mut l = s2 - s;
                if l <= 0 {
                    l += n * k;
                }
                let m = lcm(l, n * k);
                x = std::cmp::min(x, m / l);
                y = std::cmp::max(y, m / l);
            }
        }
    }
    println!("{} {}", x, y);
}

