fn div(mut n: usize, mut k: usize) -> usize {
    while k > 0 {
        let rem = n % 10;
        if rem < k {
            k = k - rem - 1;
            n = n / 10;
        } else {
            n = n - k;
            k = 0;
        }
    }
    n
}

