macro_rules! decl_error{
    ($($error:ident)*) => {
        #[derive(Debug)]
        pub enum Error {
            $($error($error),)*
        }

        $(
            impl From<$error> for Error {
                fn from(e: $error) -> Self {
                    Error::$error(e)
                }
            }
        )*

        pub type Result<T> = std::result::Result<T, Error>;
    }

}

