fn int_len(inp: Res) -> Res {
    match inp {
        0..=9 => 1,
        10..=99 => 2,
        100..=999 => 3,
        1000..=9999 => 4,
        10000..=99999 => 5,
        100000..=999999 => 6,
        1000000..=9999999 => 7,
        10000000..=99999999 => 8,
        100000000..=999999999 => 9,
        1000000000..=9999999999 => 10,
        10000000000..=99999999999 => 11,
        100000000000..=999999999999 => 12,
        1000000000000..=9999999999999 => 13,
        _ => unreachable!()
    }
}

fn solve(k: Res) -> char {
    // counter for digits
    let mut n: Res = 1;
    // Potential number of the digit we search
    let mut d: Res = 1;
    while n<k {
        d += 1;
        n += int_len(d);
        //dbg!((n,d));
    }
    let delta = n-k;
    // At tis point we know our digit d and the index of the number we search for.

    let d_str = format!("{}", d);
    let d_len = int_len(d);
    let idx = (d_len - delta - 1) as usize;
    //println!("n{} d{} k{} delta{} idx{}", n, d, k, delta, idx);
    let result = d_str.chars().nth(idx).expect("Invalid index");
    result
}

