    let mut res = HashSet::new();

    if n % 2 == 0 {
        res.insert(2);
        res.insert(n / 2);
    }
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 {
            res.push(i);
        }
        i += 2;
    }
    res
}

