use std::cmp::min;
use std::io::{self, Read, Write};
pub fn solve<R: Read, W: Write>(read: R, out: &mut W) -> io::Result<()> {
	let mut sc = Scanner::from(read);
	let n = sc.usize();
	let s = sc.token();
	let mut next = vec![[n; 26]; n + 1];
	for i in (0..n).rev() {
		next[i] = next[i + 1].clone();
		next[i][(s[i] - b'a') as usize] = i;
	}
	let mut dp = vec![vec![std::i32::MAX; n + 1]; n + 1];
	for i in 0..=n {
		dp[i][i] = 0;
	}
	for len in 1..=n {
		for l in 0..=n - len {
			let r = l + len;
			dp[l][r] = (0..26)
				.map(|a| {
					let mut sum = 0;
					let mut k = l as isize - 1;
					while k < r as isize {
						let nk = min(next[(k + 1) as usize][a], r);
						sum += dp[(k + 1) as usize][nk];
						k = nk as isize;
					}
					sum
				})
				.min()
				.unwrap() + 1;
		}
	}
	let ans = dp[0][n];
	writeln!(out, "{}", ans)?;
	Ok(())
}
