fn is_lucky_number_with_4(val: u64) -> bool {
    let mut remain: u64 = val;
    loop {
        if remain % 4 != 0 {
            return false;
        }

        remain = remain / 4;
        if remain != 1 {
            break;
        }
    }

    true
}

fn is_lucky_number_with_7(val: u64) -> bool {
    let mut remain: u64 = val;
    loop {
        if remain % 7 != 0 {
            return false;
        }

        remain = remain / 7;
        if remain != 1 {
            break;
        }
    }

    true
}

