fn main() {
	let mut rin = reader();
	let mut rout = writer();

	let mut c0 = vec![1; 10];
	for x in rin.vb() {
		c0[(x - b'0') as usize] += 1;
	}
	let m = rin.u();
	let mut ns = 1;
	for &c in c0.iter() {
		ns *= c;
	}
	let encode = |a: &[usize]| -> usize {
		let mut res = 0;
		for i in 0..10 {
			res = res * c0[i] + a[i];
		}
		res
	};
	let decode = |a: &mut [usize], mut x: usize| {
		for i in (0..10).rev() {
			a[i] = x % c0[i];
			x /= c0[i];
		}
	};
	let mut dp = vec![vec![0; m]; ns];
	dp[0][0] = 1;
	for s in 0..ns {
		let mut a = vec![0; 10];
		decode(&mut a, s);
		let st = if s == 0 {1} else {0};
		for r in 0..m {
			let v = dp[s][r];
			if v == 0 { continue; }
			for i in st..10 {
				if a[i]+1 < c0[i] {
					a[i] += 1;
					let ss = encode(&a);
					dp[ss][(r * 10 + i) % m] += v;
					a[i] -= 1;
				}
			}
		}
	}
	let sol = dp[ns-1][0];
	writeln!(rout, "{}", sol).ok();
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let mut n: u64 = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();
    let mut cnt = vec![0; 10];
    let mut len = 0;
    while n > 0 {
        let k = (n % 10) as usize;
        cnt[k] += 1;
        len += 1;
        n /= 10;
    }
    let mut now = std::collections::BTreeMap::new();
    now.insert((cnt, 0), 1u64);
    for p in 0..len {
        let mut next = std::collections::BTreeMap::new();
        for (k, v) in now.iter() {
            let (a, rem) = k.clone();
            for d in 0..10 {
                if a[d] > 0 && !(p == 0 && d == 0) {
                    let mut b = a.clone();
                    b[d] -= 1;
                    let r = (10 * rem + d) % m;
                    *next.entry((b, r)).or_insert(0u64) += *v;
                }
            }
        }
        now = next;
    }
    let mut ans = 0;
    for (k, v) in now.iter() {
        if k.1 == 0 {
            ans += *v;
        }
    }
    println!("{}", ans);
