        if k != 0 {
            k = i - k;
        }

        let lcm = (a + k) * (b + k) / (i * gcd((a + k) / i, (b + k) / i));
        if lcm < lcm_min {
            lcm_min = lcm;
            min_k = k;
        }
    }
    if md != 0 {
        for i in vec {
            let mut k = a % i;
            if k != 0 {
                k = i - k;
            }

            let lcm = (a + k) * (b + k) / (i * gcd((a + k) / i, (b + k) / i));
            if lcm < lcm_min {
