struct Scanner<B: io::BufRead> {
    reader: B,
    buffer: Vec<String>,
}

impl<B: io::BufRead> Scanner<B> {
    fn new(reader: B) -> Self {
        Self {
            reader,
            buffer: Vec::new(),
        }
    }

    fn next<T: std::str::FromStr>(&mut self) -> T
    where
        T::Err: std::fmt::Debug,
    {
        if let Some(s) = self.buffer.pop() {
            T::from_str(&s).unwrap()
        } else {
            let mut s = String::new();
            let r = self.reader.read_line(&mut s).unwrap();
            assert!(r > 0);
            self.buffer = s.split_whitespace().rev().map(String::from).collect();
            return self.next();
        }
    }
}

fn fix(balance: i64) -> i64 {
    if balance >= 0 {
        return balance;
    }

    let temp = balance * -1;
    let last_dig = temp % 10;
    let seclast_dig = (temp / 10) % 10;

    if last_dig > seclast_dig {
        balance / 10
    } else {
        (balance / 100) * 10 + last_dig
    }
}

