fn solve<Inner: BufRead, Output: Write>(inf: &mut Input<Inner>, ouf: &mut Output) {
	let (n, d) = read!(inf,usize,i32);
	let mut a = vec![0; n];
	for i in 0..n {
		a[i] = read!(inf,i32);
	}
	a.sort_unstable();
	let (mut p1, mut p2) = (0, n - 1);
	while p2 > 0 && a[p2] - a[0] > d {
		p2 -= 1;
	}
	while p1 < n - 1 && a[n - 1] - a[p1] > d {
		p1 += 1;
	}
	writeln!(ouf, "{}", min(p1, n - 1 - p2));
}

