            for i in 0..3 {
                if c[i] > n[i] && r >= ((c[i] - n[i]) * p[i]) as u64 {
                    r -= ((c[i] - n[i]) * p[i]) as u64;
                    n[i] = c[i];
                }
            }
        } else {
            break;
        }
        let mut buying = std::usize::MAX;
        for i in 0..3 {
            if c[i] != 0 {
                buying = buying.min(n[i] / c[i]);
            }
        }
        if buying == 0 {
