fn main() {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = io::BufWriter::new(stdout.lock());

    let mut word = scan.next();

    if word.len() == 0 {
        return;
    }

    if word.len() == 1 {
        writeln!(out, "{}", word.to_uppercase()).ok();
    } else {
        if strmbexpr(
            |c| c.is_uppercase() || c.is_whitespace(),
            word.chars().skip(1).collect::<Vec<_>>(),
        ) {
            // invert the caps
            // this is by far the most evil code I've ever written in Rust
            unsafe {
                let ptr = word.as_mut_ptr();
                for i in 1..word.len() {
                    std::ptr::write(
                        ptr.offset(i as isize),
                        word.as_bytes()[i] + ('a' as u8 - 'A' as u8),
                    );
                }
                if *ptr >= 'a' as u8 {
                    std::ptr::write(ptr, word.as_bytes()[0] - 32)
                } else {
                    std::ptr::write(ptr, word.as_bytes()[0] + ('a' as u8 - 'A' as u8))
                }
            }

            writeln!(out, "{}", word).ok();
        } else {
            writeln!(out, "{}", word).ok();
        }
    }
}

