pub fn fix_case(s: &str) -> String {
    let s = s.to_owned();

    if is_mistyped(&s) {
        let mut s = s.into_bytes();
        s.make_ascii_lowercase();
        s[0] = s[0].to_ascii_uppercase();
        String::from_utf8(s).unwrap()
    } else {
        s
    }
}

pub fn is_mistyped(s: &str) -> bool {
    let mut iter = s.bytes();
    iter.next();
    iter.all(|c| c >= b'A' && c <= b'Z')
}

