}

impl Cin {
    fn new() -> Self {
        Cin { data: LinkedList::new() }
    }
    fn read_line(&self) -> String {
        let mut s: String = String::new();
        io::stdin().read_line(&mut s).expect("err");
        s
    }
    fn read_str(&mut self) -> String {
        if self.data.len() == 0 {
            let s = self.read_line();
//            let split = s.split("\\s+");
            let split = s.split_whitespace();
            for el in split {
                self.data.push_back(String::from(el));
            }
        }
        self.data.pop_front().expect("empty")
    }
    fn read_int(&mut self) -> i64 {
        self.read_str().parse().expect("err parse")
    }
    fn read_vec(&mut self, size: &i64) -> Vec<i64> {
        let mut v: Vec<i64> = Vec::new();
        for _i in 0..*size {
            v.push(self.read_int());
        }
        v
    }
}

