macro_rules! read_line {
    ([$t: ty]) => {{
        read_line().split_whitespace().map(|token| {
            <$t as std::str::FromStr>::from_str(token).expect(
                &format!(concat!("Could not parse {} into ", stringify!($t)), token))
        })
    }};
    ($($t: ty),*) => {{
        let line = read_line();
        let mut iter = line.split_whitespace();
        ($({
            let token = iter.next().expect("Not enough tokens");
            <$t as std::str::FromStr>::from_str(token).expect(
                &format!(concat!("Could not parse {} into ", stringify!($t)), token))
        }),*)
    }};
}

fn main() {
    read_line!(usize);
    enum State {
        Up,
        Hold,
        Down,
    }
    use State::*;
    let mut state = Up;
    let mut prev = 0;
    let mut ans = true;
    for x in read_line!([u16]) {
        match state {
            Hold => {
                if x > prev {
                    ans = false;
                    break;
                }
            }
            Down => {
                if x >= prev {
                    ans = false;
                    break;
                }
            }
            Up => {}
        }
        state = if x < prev {
            Down
        } else if x > prev {
            Up
        } else {
            Hold
        };
        prev = x;
    }
    println!("{}", if ans { "YES" } else { "NO" });
}

#[macro_export]
macro_rules! scanln {
  ($($var:ident : $ty:path),+) => {
    $(let $var: $ty;)+
    {
      use std::io;
      let mut __buf = String::new();
      io::stdin().read_line(&mut __buf).unwrap();
      let mut eles = __buf.split_whitespace();
      $($var = Scan::scan(&mut eles);)+
    }
  }
}

pub trait Scan {
  fn scan<'a, I>(eles: &mut I) -> Self where I: Iterator<Item=&'a str>;
}

macro_rules! impl_scan_single {
  ($ty:ty) => {
    impl Scan for $ty {
      fn scan<'a, I>(eles: &mut I) -> Self where I: Iterator<Item=&'a str> {
        let next = eles.next().unwrap();
        match next.parse() {
          Ok(res) => res,
          Err(_) => panic!()
        }
      }
    }
  }
}

