fn exec() {
    let mut sc = Scanner::new();
    let _: usize = sc.ne();
    let k: usize = sc.ne();
    let a = sc.ne::<String>().into_bytes();
    let start = a.iter().position(|&x| x == b'G').unwrap();
    let goal = a.iter().position(|&x| x == b'T').unwrap();
    let s = min(start, goal);
    let g = max(start, goal);
    if (g - s) % k != 0 {
        println!("NO");
        std::process::exit(1);
    }
    let mut ok = true;
    let mut cur = s;
    while cur != g {
        if a[cur] == b'#' {
            ok = false;
        }
        cur += k;
    }
    println!("{}", if ok { "YES" } else { "NO" });
}


