fn factorize(n: u64) -> Vec<(u64, u64)> {
    let mut n = n;
    let mut p = 2;
    let mut ans = Vec::new();
    while p * p <= n && n > 1 {
        let mut expo = 0;
        while n % p == 0 {
            expo += 1;
            n /= p;
        }
        if expo > 1 {
            ans.push((p, expo));
        }
        p += 1;
    }
    if n > 1{
        ans.push((n, 1));
    }
    ans
}

fn solve<R: io::BufRead, W: io::Write>(scan: &mut Scanner<R>, out: &mut W) {
