    let mut max_expo = 0;
    for (p, expo) in factors {
        min_n *= p;
        max_expo = max_expo.max(expo);
    }
    let power_of_two = factorize(max_expo.next_power_of_two());
    let (_, min_ops) = power_of_two[0];
