macro_rules! parse_line {
    ($t: ty) => ({
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        let a_str = a_str.trim();
        a_str.parse::<$t>().expect("parse error")
    });
    ($($t: ty),+) => ({
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        let mut a_iter = a_str.split_whitespace();
        (
            $(
            a_iter.next().unwrap().parse::<$t>().expect("parse error"),
            )+
        )
    })
}

macro_rules! parse_line_to_vec {
    ($t: ty) => {{
        let mut a_str = String::new();
        std::io::stdin().read_line(&mut a_str).expect("read error");
        (a_str
            .split_whitespace()
            .map(|x| x.parse::<$t>().unwrap())
            .collect::<Vec<$t>>())
    }};
}

fn solve() {
    let mut n = parse_line!(u32);
    let mut max: u32 = 0;
    let mut min = std::u32::MAX;
    let mut val: u32 = 1;
    for i in 2..n {
        if i * i > n {
            break;
        }
        if n % i != 0 {
            continue;
        }
        val *= i;
        let mut cnt = 0;
        while n % i == 0 {
            n /= i;
            cnt += 1;
        }
        max = std::cmp::max(max, cnt);
        min = std::cmp::min(min, cnt);
    }
    if n != 1 {
        max = std::cmp::max(max, 1);
        min = std::cmp::min(min, 1);
        val *= n;
    }
    let mult = if max != min || max & (max - 1) != 0 {1} else {0};
    if max & (max - 1) != 0 {
        max <<= 1;
    }
    while max & (max - 1) != 0 {
        max &= max - 1;
    }
    println!("{} {}", val, mult + max.trailing_zeros());
}

