fn bfs(initial_length: i32, abc_list: Vec<i32>) -> i32 {
    let mut answer: i32 = 0;

    //TODO: BFS, but do not return after the count is 0
    let mut queue: LinkedList<i32> = LinkedList::new();
    queue.push_back(initial_length);

    let mut step: i32 = 0;
    loop {
        if queue.len() == 0 {
            break;
        }

        let size: usize = queue.len();
        for _ in 0..size {
            let current: i32 = queue.pop_front().unwrap();

            if current < 0 {
                continue;
            }

            if current == 0 {
                answer = cmp::max(answer, step);
            }

            //subtract
            for i in 0..abc_list.len() {
                let next_result: i32 = current - abc_list[i];
                queue.push_back(next_result);
            }
        }

        step += 1;
    }

    return answer;
}

