}

fn compute(mut n: usize, x: usize, y: usize, z: usize) -> usize {
    match n % x % y % z {
        0 => {
            let mut ans = n / x;
            n %= x;
            ans += n / y;
            n %= y;
            ans += n / z;
            ans
        }
        _ => 0,
    }
}

