const DECIMAL_RADIX : u64 = 10;

fn read_line(stdin : &Stdin, line : &mut String) {
    match stdin.read_line(line) {
        Ok(_) => return,
        Err(msg) => panic!("Could not read line! Message: {}.", msg),
    }
}

fn parse_t<T : FromStr>(s : &str) -> T {
    match s.trim().parse() {
        Ok(y) => y,
        Err(_) => panic!("Could not read from string!"),
    }
}

fn read_t<T : FromStr>(stdin : &Stdin) -> T {
    let mut line = String::new();
    read_line(stdin, &mut line);
    parse_t(&line)
}

fn little_endian_digits(n : u64, ds : &mut Vec<u64>) {
    let mut x = n;
    loop {
        let d = x % 10;
        x = x / 10;
        ds.push(d);
        if x == 0 {
            break;
        }
    }
}

fn big_endian_digits(n : u64, ds : &mut Vec<u64>) {
    little_endian_digits(n, ds);
    ds.reverse();
}

fn big_endian_digits_to_number(ds : &Vec<u64>) -> u64 {
    let mut x = 0;
    for d in ds {
        x = (x * 10) + d;
    }
    x
}

fn contains(y : u64, xs : &Vec<u64>) -> bool {
    for &x in xs {
        if y == x {
            return true;
        }
    }
    false
}

fn find_replacement_digit(d : &Option<u64>, digits : &Vec<u64>) -> Option<u64> {
    let mut s = 0;
    match *d {
        None => (),
        Some(y) => {
            s = y + 1;
        },
    }
    for i in s .. DECIMAL_RADIX {
        if contains(i, digits) {
            // Do nothing ...
        } else {
            return Some(i);
        }
    }
    None
}

fn next_with_distinct_digits(n : u64) -> u64 {
    let mut b_e_digits = vec![];
    big_endian_digits(n, &mut b_e_digits);
    let orig_level = b_e_digits.len() - 1;
    let mut level = orig_level;
    let mut c_d_o = Some(b_e_digits[level]);
    loop {
        let r_d_o = find_replacement_digit(&c_d_o, &b_e_digits);
        match r_d_o {
            None => {
                b_e_digits.pop();
                level = level - 1;
                c_d_o = Some(b_e_digits[level]);
            },
            Some(r_d) => {
                b_e_digits[level] = r_d;
                if level < orig_level {
                    b_e_digits.push(DECIMAL_RADIX);
                }
                level = level + 1;
                c_d_o = None;
            }
        }
        if level > orig_level {
            break;
        }
    }
    big_endian_digits_to_number(&b_e_digits)
}

fn main() {
    let stdin = io::stdin();
    let n = read_t(&stdin);
    println!("{}", next_with_distinct_digits(n));
}

