struct Scanner { stdin: io::Stdin, buffer: VecDeque<String>, }
#[allow(dead_code)]
impl Scanner {
    fn new() -> Scanner { Scanner { stdin: io::stdin(), buffer: VecDeque::new() } }
    fn reserve(&mut self) {
        while self.buffer.len() == 0 {
            let mut line = String::new();
            let _ = self.stdin.read_line(&mut line);
            for w in line.split_whitespace() {
                self.buffer.push_back(String::from(w));
            }
        }
    }
    fn cin<T: FromStr>(&mut self) -> T {
        self.reserve();
        match self.buffer.pop_front().unwrap().parse::<T>() {
            Ok(a) => a,
            Err(_) => panic!("parse err")
        }
    }
    fn get_char(&mut self) -> char {
        self.reserve();
        let head = self.buffer[0].chars().nth(0).unwrap();
        let tail = String::from( &self.buffer[0][1..] );
        if tail.len()>0 { self.buffer[0]=tail } else { self.buffer.pop_front(); }
        head
    }
}

#[derive(Debug)]
struct RhombusIterator{
    current: isize,
    count: isize,
    total: isize,
}

impl RhombusIterator{
    pub fn new() ->Self{
        RhombusIterator{
            current: 1,
            count: 0,
            total: 1,
        }
    }
}

impl Iterator for RhombusIterator{
    type Item = isize;

    fn next(&mut self) -> Option<Self::Item> {
        match self.current{
            1 => {},
            _ => {
                self.total += 2* self.current + (2* self.count);
                self.count += 1;
            },
        }
        self.current +=1;
        Some(self.total)
    }
}

