fn main() {
    let str = "010";
    let trimmed = str.trim();
    let mut negative = false;
    let mut lookup = &trimmed[..];
    if trimmed.starts_with('-') {
        negative = true;
        lookup = &trimmed[1..];
    }
    if trimmed.starts_with('+') {
        negative = false;
        lookup = &trimmed[1..];
    }

    let digits = lookup.chars().take_while(|c| c.is_digit(10)).collect::<Vec<_>>();
    let mut answer: i64 = 0;

    for d in digits.iter().map(|c| c.to_digit(10).unwrap()) {
        answer *= 10;

        answer += match negative {
            true => -1 * d as i64,
            false => d as i64,
        };

        if answer >= i32::max_value().into() {
            answer = i32::max_value() as i64;
            break;
        }
        if answer <= i32::min_value().into() {
            answer = i32::min_value() as i64;
            break;
        }
    }

    println!("{}", answer);
}

