fn main() {
    let (n, t, k, d) = {
        let input = get_line();
        let mut it = input.split_whitespace().map(|k| k.parse::<u32>().unwrap());
        (
            it.next().unwrap(),
            it.next().unwrap(),
            it.next().unwrap(),
            it.next().unwrap(),
            )
    };

    // n + r = k * x;
    // n = k * x - r ; k < -r <= 0
    // n = k * x + r ; k < r <= 0
    // n + k - 1 = k * x + r ; 0 <= r < k
    // n - 1 = k * (x - 1) + r

    let t1 = (n - 1) / k + 1;

    let ta = d / t;
    let tb = t1 - ta;

    if tb > 1 {
        println!("YES");
    } else {
        println!("NO");
    }
}

