fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    #[allow(unused)] macro_rules! puts { ($($format:tt)*) => (let _ = write!(out,$($format)*);); }

    let s1: Vec<char> = get_word().chars().collect();
    let s2: Vec<char> = get_word().chars().collect();

    let mut sum1 = 0;
    let mut sum2 = 0;

    for c in s1 {
	sum1 += match c {
	    '+' => 1,
	    '-' => -1,
	    _  => 0,
	}
    }

    for c in &s2 {
	sum2 += match *c {
	    '+' => 1,
	    '-' => -1,
	    _  => 0,
	}
    }

    let mut q = 0;

    for c in &s2 {
	if *c == '?' {
	    q += 1;
	}
    }


    let d: i64 = sum1 - sum2;
    let d = d.abs();

    let mut  num = 1;

    if d > q || d * q % 2 != 0 { puts!("{}", 0.0); } else {

	let m = d + (q - d) / 2;
	for i in (q - m + 1)..(q + 1) {
	    num *= i;
	}

	puts!("{}", num as f64 / (1 << q) as f64);
    }
}
