fn main() {
	let mut input = String::new();
	io::stdin().read_line(&mut input).unwrap();

	let mut iter = input.split_whitespace();
	let n: u16 = iter.next().unwrap().parse().unwrap();
	let a: u16 = iter.next().unwrap().parse().unwrap();
	let b: u16 = iter.next().unwrap().parse().unwrap();

	let mut max: u16 = (a + b) / n;
	let mut min: u16 = 1;
	let mut prev: u16 = 1;

	loop {
		let cur: u16 = (max - min) / 2 + min;

		if cur == prev {
			break;
		}

		if a / cur + b / cur >= n {
			min = cur;
		} else {
			max = cur;
		}

		prev = cur;
	}

	println!("{}", prev);
}

