fn main() {
    let (n, a, b) = scan_line!(i32, i32, i32);
    let mut l = 1;
    let mut r = n;
    while r - l > 1 {
        let m = l + (r - l) / 2;
        let ap = a / m;
        let bp = b / (n - m);
        if ap == bp {
            l = m;
            break;
        } else if ap < bp {
            r = m;
        } else {
            l = m;
        }
    }
    println!("{}", std::cmp::min(a / l, b / (n - l)));
}

