fn modpow(base: u64, expo: u64, modulo: u64) -> u64 {
    let mut ans = 1;
    let mut base = base;
    let mut expo = expo;
    while expo > 0 {
        if expo % 2 != 0 {
            ans *= base;
        }
        base = (base * base) % modulo;
        expo /= 2;
    }
    ans
}

fn is_primitive(x: u64, p: u64) -> bool {
    for i in 1..p - 1 {
        if modpow(x, i, p) == 1 {
            return false;
        }
    }
    modpow(x, p - 1, p) == 1
}

fn solve<R: io::BufRead, W: io::Write>(scan: &mut Scanner<R>, out: &mut W) {
    let p: u64 = scan.token();
    let mut ans = 0;
    for x in 1..p {
        if is_primitive(x, p) {
            ans += 1;
        }
    }
    writeln!(out, "{}", ans).ok();
}

