        let mut ans = 0;
        let mut c = 0;
        let mut k = k;
        for i in 0..n {
            if k != 0 && s[i] != t[0] {
                ans += c;
                c += 1;
                k -= 1;
            }
            if s[i] == t[0] {
                ans += c;
                c += 1;
            }
        }
        println!("{}", ans);
        return;
    }
    if k == 0 {
        let mut ans = 0;
        let mut c = 0;
        for i in 0..n {
            if s[i] == t[0] {
                c += 1;
            }
            if s[i] == t[1] {
                ans += c;
            }
        }
        println!("{}", ans);
        return;
    }

    let mut dp = vec![vec![vec![Minimal; n + 1]; k + 1]; n + 1];
