                }
                if s[i] == t[1] {
                    dp[i + 1][k][c] = dp[i + 1][k][c] * dp[i][k][c].map(|v| v + c as i64);
                } else {
                    dp[i + 1][k + 1][c] = dp[i + 1][k + 1][c] * dp[i][k][c].map(|v| v + c as i64);
                }
                if s[i] != t[0] && s[i] != t[1] {
                    dp[i + 1][k][c] = dp[i + 1][k][c] * dp[i][k][c];
                }
            }
        }
    }
    let mut ans = Minimal;
    for k in 0..=k {
        for c in 0..=n {
            ans = ans * dp[n][k][c];
        }
    }
    println!("{}", ans.unwrap());
}

