const MAX_CORD: i64 = 1e18 as i64;

fn solve(mut limit: i64, start: usize, p1: usize, p2: usize, p3: usize, cost: &Vec<Vec<i64>>) -> i64 {
    if limit < 0 {
        return -10000;
    }
    let mut count = 1;
    let mut now = start;
    while now != p1 {
        let t = ifv!(now < p1, now+1, now-1);
        if limit < cost[now][t] {
            return count;
        }
        count += 1;
        limit -= cost[now][t];
        now = t;
    }
    assert_eq!(now, p1);
    assert_ne!(now, p2);
    if limit < cost[now][p2] {
        return count;
    }
    limit -= cost[now][p2];
    count += 1;
    now = p2;

    while now != p3 {
        let t = ifv!(now < p3, now+1, now-1);
        if limit < cost[now][t] {
            return count;
        }
        count += 1;
        limit -= cost[now][t];
        now = t;
    }
    count
}

fn main() {
    input! {
        x0: i64, y0: i64, ax: i64, ay: i64, bx: i64, by: i64,
        sx: i64, sy: i64, limit: i64
    };

    let mut points = vec![(x0, y0)];
    loop {
        let (lx, ly) = *points.last().unwrap();
        if lx > MAX_CORD || ly > MAX_CORD {
            break;
        }
        points.push((lx*ax+bx, ly*ay+by));
    }
    let n = points.len();

    let mut first_cost = vec![];
    for i in 0..n {
        first_cost.push((sx-points[i].0).abs() + (sy-points[i].1).abs());
    }
    let mut pp_cost = dvec!(0; n, n);
    for i in 0..n {
        for j in 0..n {
            pp_cost[i][j] = (points[i].0-points[j].0).abs() + (points[i].1-points[j].1).abs();
        }
    }

    // debug!(points);
    // debug!(first_cost);

    assert!(n >= 2);

    let mut best = 0;
    for s in 0..n {
        if s < n-1 {
            for l in 0..=s {
                best = max(best, solve(limit - first_cost[s], s, l, s+1, n-1, &pp_cost));
            }
        }
        if s >= 1 {
            for l in s..n {
                best = max(best, solve(limit - first_cost[s], s, l, s-1, 0, &pp_cost));
            }
        }
    }

    println!("{}", best);
}

