fn parse_param() -> (usize, usize, usize) {
    let mut entry_text = String::new();
    stdin().read_line(&mut entry_text).expect("msg: &str");
    let a: Vec<&str> = entry_text.trim().split_whitespace().collect();
    (
        a[0].parse().expect(""),
        a[1].parse().expect(""),
        a[2].parse().expect(""),
    )
}
fn fact_add(x: usize, y: usize) -> usize {
    if x <= 1 {
        return y;
    }
    (x * y) + fact_add(x - 1, y)
}

