static PERMS: [[usize; 8]; 3] = [
    [2, 4, 6, 8, 10, 12, 23, 21],
    [13, 14, 5, 6, 17, 18, 21, 22],
    [3, 4, 17, 19, 10, 9, 16, 14]
];


fn shiftmod(i: usize, dir: i32) -> usize {
    let res = i as i32 + 2 * dir;
    (if res < 0 { 8 + res } else if res > 8 { res - 8 } else { res }) as usize
}

fn shift(perm: &[usize; 8], dir: i32, state: &mut Vec<i32>) {
    for i in 0..6 {
        state.swap(perm[i] - 1, perm[shiftmod(i, dir)] - 1)
    }
}

fn is_correct(state: &Vec<i32>) -> bool {
    (0..6).all(|i|
        ((i * 4)..(i * 4 + 3))
            .all(|k| state[k] == state[k + 1]))
}

fn single_move(state: &mut Vec<i32>) -> bool {
    PERMS.iter().any(|perm| {
        shift(perm, 1, state);
        is_correct(state) || {
            shift(perm, -1, state);
            shift(perm, -1, state);
            is_correct(state)
        }
    })
}

