#[derive(Copy, Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct Clock {
    hh: i32,
    mm: i32,
}

impl Clock {
    pub fn new (hh: i32, mm: i32) -> Self {
        Self {
            hh, mm
        }
    }
}

impl Sub<i32> for Clock {
    type Output = Clock;
    fn sub(self, m: i32) -> Clock {
        let mut c = self;
        let h = m / 60;
        c.hh -= h;
        c.mm -= m;
        if c.mm < 0 {
            c.hh -= 1;
            c.mm = 60 + self.mm;
        }
        c
    }
}

fn find_lucky(c: &Clock) -> bool {
    if c.hh / 10 == 7 || c.hh % 10 == 7 || c.mm / 10 == 7 || c.mm % 10 == 7 {
        true
    } else {
        false
    }
}

