#[derive(Debug, Clone, Copy)]
struct Time {
    hh: u8,
    mm: u8,
}

impl Time {
    fn new(hour: u8, min: u8) -> Time {
        Time {
            hh: hour,
            mm: min,
        }
    }

    fn lucky(&self) -> bool {
        // 7 cannot be appear in the 10s spot so we only have to check ones
        self.mm % 10 == 7 || self.hh % 10 == 7
    }
}

impl Sub<u8> for Time {
    type Output = Time;

    fn sub(self, mins: u8) -> Time {
        if mins < self.mm {
            Time { hh: self.hh, mm: self.mm - mins }
        } else if self.hh >= 1 {
            Time { hh: self.hh - 1, mm: self.mm + 60 - mins }
        } else {
            // going back a day
            Time { hh: 23, mm: self.mm + 60 - mins }
        }
    }
}

