        return;
    }

    // Find minimum
    let minimum = if n - (a1 * (k1 - 1)) - (a2 * (k2 - 1)) > 0 {
        n - (a1 * (k1 - 1)) - (a2 * (k2 - 1))
    } else {
        0
    };

    // Find maximum
    let mut maximum: i128 = 0;
    let mut cards_left = n;
    if (a1 * k1) < (a2 * k2) {
        cards_left -= a1 * k1;
        maximum += if cards_left >= 0 { a1 + (cards_left / k2) } else { n / k1 };
    } else {
        cards_left -= a2 * k2;
        maximum += if cards_left >= 0 { a2 + (cards_left / k1) } else { n / k2 };
    }

