fn factors(n: u64, max: Option<u64>) -> Vec<u64> {
    let sqrt = (n as f64).sqrt() as u64;
    let mut ret = Vec::<u64>::new();
    for i in 1..=sqrt {
        match max {
            Some(x) if i > x => {
//                println!("{}, {}", i, x);
                break;
            }
            _ => {}
        }
        if n % i == 0 {
            ret.push(i);
        }
    }
//    let ret = (1..=sqrt).rev().filter(|c| n % c == 0).collect::<Vec<_>>();
    return ret;
}

