            input.split_ascii_whitespace()
                .map(|x| x.parse::<i8>().unwrap())
                .collect::<Vec<i8>>()
        );
        input.clear();
    }
    print!("{}", beautiful_matrix(matrix));
    Ok(())
}
fn beautiful_matrix(matrix: Vec<Vec<i8>>) -> i8 {
    let mut distance: i8 = 0;
    let mut count: i8 = 0;
    for v in matrix {
        count += 1;
        distance += {
            (2 - v.iter()
                .position(|&x| x == 1)
                .unwrap_or(0) as i8)
                .abs()
        };
        if distance != 0 {
            distance += {
                (2 - count).abs()
            };
            break;
        }
    }distance
}
