pub fn main() {
    let n = read!(i64);
    let k = read!(i64);
    let A = read!(i64);
    let B = read!(i64);

    let mut x = n;
    let mut s = 0;
    while n > 1 {
        if x < k {
            s += (x - 1) * A;
            break;
        }

        let r = x % k;
        if r != 0 {
            x -= r;
            s += r * A;
            continue;
        }

        let q = x / k;
        s += min((x - q) * A, B);
        x = q;
    }

    println!("{}", s);
    return;
}

