const MOD: u64 = 998244353;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: u64 = sc.read();
    let m: u64 = sc.read();

    let comb = Combination::new(m, MOD);
    if n == 2 {
        println!("{}", m);
        return;
    }
    let c = mint(comb.get(m, n - 1));
    let ans = c * (n - 2) * mint(2).pow(n - 3);
    println!("{}", ans.value());
}

fn mint(v: u64) -> ModInt<u64> {
    ModInt::new(v, MOD)
}
