struct R;
impl PURQ for R {
    // B...BA...A
    // でBの数、Aの数
    type T = (usize, usize);
    fn fold(l: &Self::T, r: &Self::T) -> Self::T {
        if r.0 == 0 {
            (l.0, l.1 + r.1)
        } else {
            (l.0 + r.0, r.1)
        }
    }
    fn e() -> Self::T {
        (0, 0)
    }
}

fn run() {
    input! {
        s: bytes,
        t: bytes,
        q: usize,
        ask: [(usize1, usize, usize1, usize); q],
    }
    let mut seg_s = SegmentTreePURQ::<R>::new(s.len());
    for (i, s) in s.iter().enumerate() {
        if *s == b'A' {
            seg_s.update_tmp(i, (0, 1));
        } else {
            seg_s.update_tmp(i, (1, 0));
        }
    }
    seg_s.update_all();
    let mut seg_t = SegmentTreePURQ::<R>::new(t.len());
    for (i, s) in t.iter().enumerate() {
        if *s == b'A' {
            seg_t.update_tmp(i, (0, 1));
        } else {
            seg_t.update_tmp(i, (1, 0));
        }
    }
    seg_t.update_all();
    let mut out = String::new();
    for (a, b, c, d) in ask {
        let ans = || -> bool {
            let (x, y) = seg_s.find(a, b);
            let (z, w) = seg_t.find(c, d);
            let mut ans = false;
            if x == 0 {
                if z > 0 {
                    ans |= y > w && z % 2 == 0;
                } else {
                    ans |= (y - w) % 3 == 0;
                }
                return ans;
            }
            if z >= x && (z - x) % 2 == 0 && y >= w {
                let d = (z - x) / 2;
                let mut ok = false;
                ok |= (y - w) % 3 == 0;
                ok |= d > 0 && y > w;
                ans |= ok;
            }
            ans
        }();
        if ans {
            out.push('1');
        } else {
            out.push('0');
        }
    }
    println!("{}", out);
}

