fn run() {
    input! {
        n: usize,
    }
    let mut factor = (0..=n).collect::<Vec<_>>();
    let mut mobius = vec![1i8; n + 1];
    let mut sub = 0;
    let mut prime = vec![];
    let mut cnt = vec![];
    for i in 2..=n {
        if i == factor[i] {
            prime.push(i);
            let mut c = 0;
            let mut d = 0;
            for j in 1..=(n / i) {
                let p = &mut factor[j * i];
                if i <= *p {
                    *p = i;
                    c += 1;
                } else {
                    d += 1;
                }
                mobius[j * i] *= -1;
            }
            sub += c * d;
            cnt.push(c);
            let pp = i.saturating_mul(i);
            for j in 1..=(n / pp) {
                mobius[j * pp] = 0;
            }
        }
    }
    let mut ans = 0i64;
    for (i, mobius) in mobius.iter().enumerate().skip(2) {
        let s = *mobius as i64;
        if s != 0 {
            let cnt = (n / i) as i64;
            ans -= cnt * (cnt - 1) / 2 * s;
        }
    }
    while prime.last().map_or(false, |p| 2 * *p > n) {
        prime.pop();
        cnt.pop();
    }
    /*
    for (i, (a, x)) in cnt.iter().zip(prime.iter()).enumerate() {
        for (b, y) in cnt.iter().zip(prime.iter()).take(i) {
            if *x * *y <= n {
                ans += 2 * *a * *b;
            } else {
                ans += 3 * *a * *b;
            }
        }
    }
    */
    ans -= 2 * sub;
    let mut sum = 0;
    let mut x = 0;
    let mut two = 0;
    for (i, (c, p)) in cnt.iter().zip(prime.iter()).enumerate() {
        while x < i && *p * prime[x] <= n {
            two += cnt[x];
            x += 1;
        }
        while x > 0 && *p * prime[x - 1] > n {
            x -= 1;
            two -= cnt[x];
        }
        ans += two * *c * 2 + (sum - two) * *c * 3;
        sum += *c;
    }
    println!("{}", ans);
}

