struct DSU {
    p: Vec<usize>,
    s: Vec<usize>,
}

impl DSU {
    fn new(n: usize) -> Self {
        Self {
            p: (0..n).collect(),
            s: vec![1; n],
        }
    }

    fn find(&mut self, mut i: usize) -> usize {
        while i != self.p[i] {
            self.p[i] = self.p[self.p[i]];
            i = self.p[i];
        }
        i
    }

    fn union(&mut self, mut i: usize, mut j: usize) -> usize {
        i = self.find(i);
        j = self.find(j);
        if i == j { return i; }
        let (i, j) = if self.s[i] < self.s[j] { (i, j) } else { (j, i) };
        self.p[i] = j;
        self.s[j] += self.s[j];
        j
    }

    fn classes(&self) -> usize {
        self.p.iter().collect::<BTreeSet<_>>().len()
    }
}

fn main() -> Result<(), io::Error> {
