fn calculate_nth_divisor(n: i64, k: i64) -> Option<i64> {
    if k > n {
        return None;
    }

    let mut divisors = Vec::<i64>::with_capacity((k / 2) as usize);
    let max_small_divisor = (n as f64).sqrt().trunc() as i64;
    let mut count = k;

    for x in 1..=max_small_divisor {
        if n % x == 0 {
            count -= 1;
        }
        if count == 0 {
            return Some(x);
        } else {
            divisors.push(x);
        }
    }

    let size = divisors.len() as i64;
    let n_is_square = n == divisors.last().unwrap().pow(2);
    // dbg!(n, k, size, n_is_square, &divisors);
    if count > size || count == size && n_is_square {
        None
    } else {
        let mut idx = (size as i64 - count) as usize;
        if n_is_square {
            idx -= 1;
        }
        Some(n / divisors[idx])
    }
}

