fn exp(upto: usize, k: usize) {
    let mut cnt = vec![0; upto];
    for w in 1..upto {
        let mut ww = w;
        loop {
            cnt[ww] += 1;
            if ww == 1 {
                break;
            }
            if ww % 2 == 0 {
                ww /= 2;
            } else {
                ww -= 1;
            }
        }
    }
    let mut up = 0;
    for w in (1..upto).rev() {
        if cnt[w] > up {
            up = cnt[w];
            // debug!(w, up);
        }
    }
    for w in (1..upto).rev() {
        if cnt[w] >= k {
            println!("{}", w);
            break;
        }
    }
}

fn main() {
    input! {
        n: i64, k: i64
    };

    if n <= 100 {
        exp((n+1) as usize, k as usize);
        return;
    }

    let mut ans = -1;
    let mut tbl = vec![(n, 1), (n-1, ifv!(n % 2 == 0, 1, 2)), (n-2, ifv!(n % 2 == 0, 2, 1))];
    loop {
        // debug!(tbl);
        for &(f, l) in &tbl {
            if k <= l {
                ans = f;
                break;
            }
        }
        if tbl[0].0 <= 1 {
            break;
        }
        if ans != -1 {
            break;
        }

        let mut ntbl: Vec<(i64, i64)> = vec![];
        let tn = tbl.len();
        for nex in 0..4 {
            let to = tbl[0].0 / 2 - nex;
            let mut add = 1;

            // find 2*to
            {
                let mut f2 = false;
                for f in 0..tn {
                    if tbl[f].0 == 2*to {
                        add += tbl[f].1;
                        f2 = true;
                        break;
                    }
                }
                if !f2 {
                    for f in (0..tn).rev() {
                        if tbl[f].0 % 2 == 0 {
                            add += tbl[f].1;
                            break;
                        }
                    }
                }
            }

            // find to+1
            if to % 2 == 0 {
                // we already have that one...
                if nex >= 1 {
                    add += ntbl[(nex-1) as usize].1;
                } else {
                    for f in (0..tn).rev() {
                        if tbl[f].0 % 2 == 1 {
                            add += tbl[f].1;
                            break;
                        }
                    }
                }
            }
            ntbl.push((to, add));
        }
        tbl = ntbl;
    }

    // exp((n+1) as usize);
    println!("{}", ans);
}

