fn bi(x: i64, n: i64, l0: i64, r0: i64) -> i64 {
    let mut left = l0;
    let mut right = r0;

    while right - left > 1 {
        let y = (left + right) / 2;
        if x * x + y * y <= n * n {
            left = y;
        } else {
            right = y;
        }
    }
    return left;
}

