fn cost(x : i64, n : i64, k : i64) -> i64 {
   let left_limit = min(k, x - 1);
   let right_limit = min(n - k - 1, x - 1);

   let left_cost = left_limit*x - (left_limit*(left_limit+1)/2);
   let right_cost = right_limit*x - (right_limit*(right_limit+1)/2);

   let left_extra = max(k - left_limit, 0);
   let right_extra = max((n - k - 1) - right_limit, 0);

   x + left_cost + right_cost + left_extra + right_extra
}

fn search(n : i64, k : i64, m : i64) -> i64 {
   let mut upper = m;
   let mut lower = 1;
   let mut middle = 0;

   while lower <= upper {
      middle = (lower + upper)/2;
      let c = cost(middle, n, k);

      if c < m {
         lower = middle + 1;
      } else if c > m {
         upper = middle - 1;
      } else {
         break;
      }
   }

   middle
}

