        let mut best_payment = 0;
        for i in 0..costs.len() {
            let liters = 1 << i;
            if liters < need {
                let bottles = need / liters;
                let remains = need-bottles*liters;
                let payment = payment+bottles*costs[i]; 
                let payment = if remains > 0 {
                    search(costs, remains, payment)
                } else {
                    payment
                };
                if payment < best_payment || best_payment == 0 {
                    best_payment = payment;
                }
            } else {
                let payment = payment+costs[i];
                if payment < best_payment || best_payment == 0 {
                    best_payment = payment;
                }
            }
        }
        best_payment
    }

