fn count_good_players(player_count: u64, last_good_index: u64) -> u64 {
    let mut count: u64 = 0;
    let stdin = std::io::stdin();
    let mut iter = stdin.lock().split(b' ');

    for _ in 0..last_good_index {
        let buf = iter.next().unwrap().unwrap();
        let score = std::str::from_utf8(buf.as_slice()).unwrap().trim().parse::<u64>().unwrap();
        if score == 0 {
            return count;
        }
        count += 1;
    }

    let buf = iter.next().unwrap().unwrap();
    let last_good_score = std::str::from_utf8(buf.as_slice()).unwrap().parse::<u64>().unwrap();
    if last_good_score == 0 {
        return count;
    }
    count += 1;

    if last_good_index + 1 == player_count {
        return count
    }

    loop {
        let buf = iter.next();
        if let None = buf {
            return count;
        }
        let score =
            std::str::from_utf8(buf.unwrap().unwrap().as_slice())
            .unwrap()
            .parse::<u64>()
            .unwrap();
        if score < last_good_score {
            break;
        }
        count += 1;
    }

    count
}


