    let k = lines
        .next()
        .unwrap()
        .unwrap()
        .split_whitespace()
        .last()
        .unwrap()
        .parse::<usize>()
        .unwrap();

    writeln!(stdout, "{}", &calc(&lines.next().unwrap().unwrap(), k))?;

    Ok(())
}

fn calc(s: &str, k: usize) -> usize {
    let mut nums = s.split_whitespace().map(|s| s.parse().unwrap());
    for i in 0..k-1 {
        let n: usize = nums.next().unwrap();
        if n == 0 {
            return i;
        }
    }
    let n = nums.next().unwrap();
    if n == 0 {
        return k;
    }
    for i in 0.. {
        if nums.next().unwrap() != n {
            return k + i
        }
    }
    k
}

