    for c in a.chars() {
        counts[c.to_digit(10).unwrap() as usize] += 1;
    }

    let mut fa = [0u64; 30];

    let with_zero = count(&mut counts, 0, &mut fa);
    let mut correct = with_zero;
    if counts[0] > 0 {
        counts[0] = 0;
        correct -= count(&mut counts, 0, &mut fa);
    }
    println!("{}", correct);
}

fn factorial(n: u64, fa: &mut [u64]) -> u64 {
    if n == 0 {
        fa[n as usize] = 1;
    } else if fa[n as usize] == 0 {
        fa[n as usize] = factorial(n - 1, fa) * n;
    }
    return fa[n as usize];
}

fn count(counts: &mut [u64], change_here: usize, fa: &mut [u64]) -> u64 {
    if change_here == 10 {
        // All numbers are fixed now
        let numerator = factorial(counts.iter().sum(), fa);
        let mut denominator = 1;
        for c in counts {
            denominator *= factorial(*c, fa);
        }
        return numerator / denominator;
    }

    if counts[change_here] == 0 {
        return count(counts, change_here + 1, fa);
    }

    let mut add = 0;
    for i in 1..(counts[change_here] + 1) {
        counts[change_here] = i;
        add += count(counts, change_here + 1, fa);
    }
    return add;
}

