fn swaper(v: &mut Vec<Gender>, len: usize) {
    let mut to_swap: Vec<(usize, usize)> = vec![];
    for i in 0..(len - 1) {
        if v[i] == Gender::B && v[i + 1] == Gender::G {
            to_swap.push((i, i + 1))
        }
    }
    for (i, i2) in to_swap {
        v.swap(i, i2)
    }
}

