use std::cmp::min;

fn get_max_days(a: u32, b: u32, c: u32) -> u32 {
    let full_week_num: u32 = min(a / 3, min(b / 2, c / 2));
    let a_rest: u32 = a - 3 * full_week_num;
    let b_rest: u32 = b - 2 * full_week_num;
    let c_rest: u32 = c - 2 * full_week_num;

    let mut extra_days_max: u32 = 0;
    for start_weekday in 0..6 {
        let mut weekday: u32 = start_weekday;
        let mut extra_days: u32 = 0;
        let mut a_rest1: u32 = a_rest;
        let mut b_rest1: u32 = b_rest;
        let mut c_rest1: u32 = c_rest;
        loop {
            if (weekday == 0) || (weekday == 3) || (weekday == 6) {
                if a_rest1 > 0 {
                    a_rest1 -= 1;
                } else {
                    break;
                }
            }
            else if (weekday == 1) || (weekday == 5) {
                if b_rest1 > 0 {
                    b_rest1 -= 1;
                } else {
                    break;
                }
            }
            else {
                if c_rest1 > 0 {
                    c_rest1 -= 1;
                } else {
                    break;
                }
            }

            extra_days += 1;
            weekday += 1;
            weekday %= 7;
        }

        if extra_days > extra_days_max {
            extra_days_max = extra_days;
        }
    }

    return 7 * full_week_num + extra_days_max;
}

