#[derive(Debug,Clone,Copy,Default)]
struct Problem {
    buf: [u8;9],
    len: u8,
}

impl Problem {
    fn as_slice(&self) -> &[u8] {
        &self.buf[0..self.len as usize]
    }
}

fn loc(d: u8) -> (u8,u8) {
    assert!(d < 10);
    if d == 0 {
        (1,3)
    } else {
        ((d-1)%3,(d-1)/3)
    }
}

fn read_problem() -> Problem {
    let stdin = std::io::stdin();
    let mut lines = stdin.lock().lines();

    let ct = str::parse::<u8>(&lines.next().unwrap().unwrap()).unwrap();
    let mut ret = Problem::default();
    for (c,b) in lines.next().unwrap().unwrap().chars().zip(ret.buf.iter_mut()) {
        *b = c.to_digit(10).unwrap() as u8;
        ret.len += 1;
    }
    assert_eq!(ret.len, ct);
    assert!(lines.next().is_none());
    ret
}

fn solve(problem: Problem) -> bool {
    let mut min_x = u8::max_value();
    let mut min_y = u8::max_value();
    let mut max_x = 0;
    let mut max_y = 0;
    let mut max_side_y = 0;

    for &d in problem.as_slice() {
        let (x,y) = loc(d);
        if x < min_x {
            min_x = x;
        } else if x > max_x {
            max_x = x;
        }
        if y < min_y {
            min_y = y;
        } else if y > max_y {
            max_y = y;
        }
        if x != 1 && y > max_side_y  {
            max_side_y = y;
        }
    }

    let dx = max_x - min_x;
    let dy = max_y - min_y;
    let dsy = max_side_y - min_y;
    writeln!(&mut std::io::stderr(), "{:?}", (dx,dy,dsy)).unwrap();
    dy == 3 || (dx,dsy) == (2,2)
}

fn main() {
    let p = read_problem();
    println!("{}", if solve(p) { "YES" } else { "NO" });
}

