// 同じ値のみを聞き出す戦略
// 同じ値のみを残せるように聞く戦略
// 同じ値を残せるように聞く戦略ができるならのみを聞き出すことも可能
//
// 同じ値のみを残す
// a をk 個聞き出せる条件は
// aを使わないで(k - i) * a を作れないこと
// 分割統治bitset?

use std::cmp::*;

fn run() {
    input! {
        n: usize,
        a: [usize; n],
    }
    let mut a = a.into_iter().map(|a| (a, 1)).collect::<Vec<_>>();
    a.sort();
    a.dedup_by(|a, b| {
        a.0 == b.0 && {
            b.1 += a.1;
            true
        }
    });
    let w = n * 100;
    let mut dp = vec![vec![0u8; w + 1]; n + 1];
    dp[0][0] = 1;
    for &(a, c) in a.iter() {
        for i in (1..=n).rev() {
            for j in a..=w {
                let mut v = dp[i][j];
                for k in 1..=min(j / a, min(i, c)) {
                    v = v.saturating_add(dp[i - k][j - k * a]);
                }
                dp[i][j] = v;
            }
        }
    }
    /*
    for i in 0..=n {
        for j in 0..=w {
            print!("{} ", dp[i][j]);
        }
        println!();
    }
    */
    let s = a.iter().fold(0, |s, a| s + a.0 * a.1);
    let mut ans = 1;
    for &(a, c) in a.iter() {
        for k in 2..=c {
            if dp[k][k * a] == 1 || dp[n - k][s - k * a] == 1 {
                ans = max(ans, k);
            }
        }
    }
    println!("{}", ans);
}

