use std::cmp::Ordering;

#[derive(PartialEq)]
struct Segment {
  start: usize,
  len: usize
}

impl Segment {
  fn min_dist(&self) -> usize {
    (self.len + 1) / 2
  }

  fn split(self) -> Box<Iterator<Item=Self>> {
    let mut segments = Vec::new();
    let segment1;
    let segment2;
    if self.len % 2 == 0 {
      segment1 = Segment { start: self.start, len: self.len / 2 - 1 };
      segment2 = Segment { start: self.start + self.len / 2, len: self.len / 2 };
    } else {
      segment1 = Segment { start: self.start, len: self.len / 2 };
      segment2 = Segment { start: self.start + self.len / 2 + 1, len: self.len / 2 };
    }
    if segment1.len > 0 { segments.push(segment1); }
    if segment2.len > 0 { segments.push(segment2); }
    Box::new(segments.into_iter())
  }

  fn house(&self) -> usize {
    if self.len % 2 == 0 {
      self.start + self.len / 2 - 1
    } else {
      self.start + self.len / 2
    }
  }
}

impl PartialOrd for Segment {
  fn partial_cmp(&self, them: &Self) -> Option<Ordering> {
    let (o_len, t_len) = (self.min_dist(), them.min_dist());
    Some(match o_len.cmp(&t_len) {
      Ordering::Less => Ordering::Greater,
      Ordering::Greater => Ordering::Less,
      Ordering::Equal => self.start.cmp(&them.start)
    })
  }
}

