pub struct BinHeap<T> {
  pub elements: Vec<T>
}

pub fn left_child(i: usize) -> usize { (i * 2) + 1 }
pub fn right_child(i: usize) -> usize { (i * 2) + 2 }
pub fn parent(i: usize) -> usize { i.saturating_sub(1) / 2 }

pub type HeapElementId = usize;

impl<T> BinHeap<T> {
  pub fn new() -> Self {
    BinHeap { elements: Vec::new() }
  }
  pub fn with_capacity(capacity: usize) -> Self {
    BinHeap { elements: Vec::with_capacity(capacity) }
  }
}

impl<T: PartialOrd> BinHeap<T> {
  pub fn min(&self) -> Option<&T> {
    self.elements.first()
  }

  pub fn pop_min(&mut self) -> Option<T> {
    let elements = &mut self.elements;
    if elements.is_empty() { return None; }
    let i = elements.len() - 1;
    elements.swap(0, i);
    let min = elements.pop().unwrap();
    if !elements.is_empty() {
      let mut i = 0;
      let n = elements.len();
      while i < n {
        let (l, r) = (left_child(i), right_child(i));
        let mut swap = i;
        swap = if l < n && elements[l] < elements[swap] { l } else { swap };
        swap = if r < n && elements[r] < elements[swap] { r } else { swap };
        if swap == i { break; }
        elements.swap(i, swap);
        i = swap;
      }
    }
    Some(min)
  }

  pub fn insert(&mut self, element: T) -> HeapElementId {
    let i = self.elements.len();
    self.elements.push(element);
    self.bubble(i)
  }

  pub fn reduce_key(&mut self, key: T, element_id: HeapElementId) -> HeapElementId {
    if key < self.elements[element_id] { self.elements[element_id] = key; }
    self.bubble(element_id)
  }

  fn bubble(&mut self, element_id: HeapElementId) -> HeapElementId {
    let elements = &mut self.elements;
    let mut i = element_id;
    loop {
      let parent = parent(i);
      if i == 0 || elements[parent] < elements[i] { break; }
      elements.swap(i, parent);
      i = parent;
    }
    return i;
  }
}

