struct FenwickTree {
    val: Vec<i64>,
}

impl FenwickTree {
    fn new(n: usize) -> Self {
        FenwickTree {
            val: vec![0; n + 1],
        }
    }
    fn add(&mut self, mut x: usize, v: i64) {
        while let Some(p) = self.val.get_mut(x) {
            *p += v;
            x += x & (!x + 1);
        }
    }
    fn sum(&mut self, mut x: usize) -> i64 {
        assert!(x < self.val.len());
        let mut ans = 0;
        while x > 0 {
            ans += self.val[x];
            x -= x & (!x + 1);
        }
        ans
    }
}

fn sieve(n: usize) -> Vec<i64> {
    let mut is_prime = vec![true; n + 1];
    for i in 2.. {
        if i * i > n {
            break;
        }
        if is_prime[i] {
            let mut j = i * i;
            while j <= n {
                is_prime[j] = false;
                j += i;
            }
        }
    }
    let len = is_prime.iter().skip(2).filter(|p| **p).count();
    let mut prime = Vec::with_capacity(len);
    for (i, is_prime) in is_prime.into_iter().enumerate().skip(2) {
        if is_prime {
            prime.push(i as i64);
        }
    }
    prime
}

// N 以下の素数の個数を数える
fn prime_count(n: i64) -> i64 {
    let mut m = 1;
    while (m + 1) * (m + 1) <= n {
        m += 1;
    }
    let p = sieve(m as usize);
    let bound = (n as f64).cbrt().powi(2) as i64 + 2;
    let mut query = vec![];
    let mut stack = vec![(n, p.len())];
    while let Some((n, k)) = stack.pop() {
        if k == 0 {
            continue;
        }
        let q = p[k - 1];
        if q * q > n {
            let x = match p[..k].binary_search_by(|&p| (p * p).cmp(&n)) {
                Ok(k) => k + 1,
                Err(k) => k,
            };
            stack.push((n, x));
        } else if n <= bound {
            query.push((k, n));
        } else {
            stack.push((n, k - 1));
            stack.push((n / q, k - 1));
        }
    }
    query.sort();
    query.dedup();
    let m = bound as usize;
    let mut bit = FenwickTree::new(m);
    for i in 1..=m {
        bit.add(i, 1);
    }
    let mut is_prime = vec![true; m + 1];
    let mut memo = vec![0; query.len()];
    let mut pos = 0;
    for (i, p) in p.iter().enumerate() {
        let p = *p as usize;
        let mut j = p;
        while j <= m {
            if is_prime[j] {
                bit.add(j, -1);
            }
            is_prime[j] = false;
            j += p;
        }
        while let Some(&(k, n)) = query.get(pos) {
            if k > i + 1 {
                break;
            } else {
                memo[pos] = bit.sum(n as usize);
                pos += 1;
            }
        }
        if pos >= query.len() {
            break;
        }
    }
    let mut ans = 0;
    let mut stack = vec![(n, p.len(), 1)];
    while let Some((n, k, sign)) = stack.pop() {
        if k == 0 {
            ans += sign * n;
            continue;
        }
        let q = p[k - 1];
        if q * q > n {
            let x = match p[..k].binary_search_by(|p| (p * p).cmp(&n)) {
                Ok(k) => k + 1,
                Err(k) => k,
            };
            ans += -sign * (k - x) as i64;
            stack.push((n, x, sign));
        } else if n <= bound {
            ans += sign * memo[query.binary_search(&(k, n)).unwrap()];
        } else {
            stack.push((n, k - 1, sign));
            stack.push((n / q, k - 1, -sign));
        }
    }
    ans - 1 + p.len() as i64
}

fn run() {
    let mut s = String::new();
