fn main() {

    input! {
        A: u64,
        B: u64,
        mut N: u64,
    }

    let mut turn = 0;
    let stones = vec![A,B];
    loop {
        println!("turn {}, N:{}", turn, N);
        let d = gcd(stones[turn], N);
        if N > d {
            N -= d;
            turn = 1-turn;
        } else if N==d {
            println!("== turn:{} d:{}", turn,d);
            turn = 1-turn;
            break;
        } else {
            break;
        }
    }

    println!("{}", 1-turn);
}

