fn main() {
    let n = read::<String>()
        .chars()
        .map(|c| c.to_digit(10).unwrap() as usize)
        .collect::<Vec<_>>();

    const B: usize = 500;

    let dp = n.citer().fold(
        vec![
            vec![vec![0usize; B]; B],
            vvec![vec![usize::MAX; B]; vec![1usize; B]; B],
        ],
        |prev, d| {
            // eprintln!("{:?}", prev);
            (0..2)
                .map(|t| {
                    let d = d + t;
                    let mut dp = (0..B)
                        .map(|i| {
                            let mut v = vec![usize::MAX; B];

                            if i >= d {
                                v[i - d] = prev[0][i][i - d].saturating_add(i + (i - d));
                            }

                            if i + 10 >= d && i + 10 - d < B {
                                v[i + 10 - d] =
                                    prev[1][i][i + 10 - d].saturating_add(i + (i + 10 - d))
                            }

                            v
                        })
                        .collect::<Vec<_>>();
                    for i in 0..B {
                        for j in 0..B {
                            if i > 0 {
                                dp[i][j] = min(dp[i][j], dp[i - 1][j]);
                            }
                            if j > 0 {
                                dp[i][j] = min(dp[i][j], dp[i][j - 1]);
                            }
                        }
                    }
                    dp
                })
                .collect::<Vec<_>>()
        },
    );
    let ans = dp[0][B - 1][B - 1];
    println!("{}", ans);
}

