const N:usize = 666; 


fn main() {

    let mut str = String::new();
	std::io::stdin().read_line(&mut str).expect("");
    let input :Vec<&str> = str.trim().split(" ").collect();
    let n = input[0].parse::<i32>().unwrap();
    let modn = input[1].parse::<i64>().unwrap();
    let mut dp:Vec<[i64;2]> = vec![[0;2];N*N];
    let shift = N*N/2;
    dp[shift][1]=1;
    for _i in 1..n{
        let mut new_dp:Vec<[i64;2]> = vec![[0;2];N*N];
        let i = _i as usize;
        for _j in 0..(N*N-1){
            let j = _j as usize;
            if dp[j][1]==0 &&  dp[j][0]==0{
                continue;
            }
            new_dp[j-i][1] = (new_dp[j-i][1]+dp[j][1])%modn;
            new_dp[j+1][1] = (new_dp[j+1][1]-2*dp[j][1] + modn + modn)%modn;
            new_dp[j+i+2][1]=(new_dp[j+i+2][1]+dp[j][1])%modn;

            new_dp[j+1][0] = (new_dp[j+1][0]+dp[j][1]*(i as i64))%modn;
            new_dp[j][0] = (new_dp[j][0]+(modn-dp[j][1])*(i as i64+1))%modn;
            new_dp[j-i][0] = (new_dp[j-i][0]+dp[j][1])%modn;

            let t:i64 = (i as i64 +1)*dp[j][0]%modn;
