// 一致してる間は転倒数一致、後ろの寄与も一致
// p_0 < q_0 の問題がn=2..50 で解ければいい
// 初項を決めたらあとは転倒数を保持するdpでいいんじゃ？
// N^5 になってるが
// いや7乗だこれ

fn run() {
    input!(n: usize, modulo: u32);
    StaticMod::set_modulo(modulo);
    let mut ans = M::zero();
    let mut binom = vec![vec![M::zero(); n + 1]; n + 1];
    binom[0][0] = M::one();
    for i in 1..=n {
        binom[i][0] = M::one();
        for j in 1..=i {
            binom[i][j] = binom[i - 1][j - 1] + binom[i - 1][j];
        }
    }
    let mut dp = Map::new();
    for rem in (1..=n).rev() {
        let mut next = Map::new();
        for i in 0..rem {
            for j in (i + 1)..rem {
                *next.entry(i as i32 - j as i32).or_insert(M::zero()) += binom[n][rem];
            }
        }
        let mut trans = Map::new();
        for i in 0..rem {
            for j in 0..rem {
                *trans.entry(i as i32 - j as i32).or_insert(M::zero()) += M::one();
            }
        }
        for (diff, way) in dp {
            for (d, w) in trans.iter() {
                *next.entry(diff + *d).or_insert(M::zero()) += *w * way;
            }
        }
        dp = next;
    }
    let mut ans = M::zero();
    for (diff, way) in dp {
        if diff > 0 {
            ans += way;
        }
    }
    let ans = ans.0 % modulo;
    println!("{}", ans);
}

fn main() {
    run();
}

