type Mint = ModInt<VarMod>;
fn case<I: Input, O: Write>(mut pin: I, mut out: O) {
    let (n, m): (usize, u32) = pin.parse();
    set_var_mod(m);
    let mut dp = vec![Mint::new(0); n + 1];
    dp[n] = Mint::new(1);
    let mut sum = Mint::new(0);
    for i in (1..=n).rev() {
        dp[i] += sum;
        sum += dp[i];
        let mut r = 0;
        for d in 2..=i {
            let q = i / d;
            d!(i, q);
            if q == i / (d + 1) {
                r = q;
                break;
            }
            dp[q] = dp[q] + dp[i];
