fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: i64 = sc.read();
    let mut dp = vec![0; n + 1];
    let mut suffix_sum = 0;
    dp[n] = 1;

    for cur in (2..=n).rev() {
        dp[cur] = mod_add(dp[cur], suffix_sum, m);
        suffix_sum = mod_add(suffix_sum, dp[cur], m);

        let mut min_next = n;
        for z in 2.. {
            if z * z > cur {
                break;
            }
            let next = cur / z;
            dp[next] = mod_add(dp[next], dp[cur], m);
            min_next = min_next.min(next);
        }

        for next in 1..min_next {
            let z = cur / next;
            let z_next = cur / (next + 1);
            let count = z - z_next;
            let add = ((count as i64) * dp[cur]) % m;
            dp[next] = mod_add(dp[next], add, m);
            if z_next == 1 {
                break;
            }
        }
    }
    dp[1] = mod_add(dp[1], suffix_sum, m);

    // eprintln!("{:?}", dp);
    println!("{}", dp[1]);
}

fn mod_add(x: i64, y: i64, m: i64) -> i64 {
    let r = x + y;
    if r >= m {
        r - m
    } else {
        r
    }
}

fn mod_sub(x: i64, y: i64, m: i64) -> i64 {
    let r = x + m - y;
    if r >= m {
        r - m
    } else {
        r
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write_all(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn usize0(&mut self) -> usize {
        self.read::<usize>() - 1
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

