fn count_number(n : usize, m : usize) -> usize{
    if n == 2 {
        return 2;
    }
    let mut save = vec![1; n + 1];
    for i in 2..n{
        save[i] = (save[i] + i - i / 2) % m;
        let x = save[i];
        for j in (i + 1) .. (n + 1){
            let start = if (j / (i + 1)) > 1 { j / (i + 1) } else { 1 };
            let way = (j / i) + 1 - start;
            save[j] = (save[j] + way * x) % m;
        }
    }
    return (save[n] + n - (n / 2)) % m;
}

#[allow(dead_code)]
fn count_number2(n : usize, m : i32) -> i32{
    fn div_way(x : usize, k : usize) -> i32{
        let (a, b) = ((x / k) as i32, (x / (k + 1)) as i32);
        if b > 1 { a - b } else { a - 1 }
    }

    fn diff(x : usize, k : usize) -> i32{
        div_way(x, k) - div_way(x - 1, k)
    }

    if n == 2 {
        return 2;
    }
    let mut save = vec![0; n + 1];
    save[1] = 1;
    save[2] = -2;
    for i in 2..n + 1{
        if i % 2 == 0 {
            save[i] = (save[i] + 2 * save[i - 1] + save[ i / 2 ] + diff(i, 1)) % m;
        }
        else {
            save[i] = (save[i] + 2 * save[i - 1] + diff(i, 1)) % m;
        }

        let x = save[i];
        for j in (2 * i + 1) .. (n + 1){
            save[j] = (save[j] + diff(j, i) * x) % m;
        }
    }
    return save[n];
}

