use std::cmp::max;
use std::io::{self, prelude::*, BufWriter};
use std::str::FromStr;

type M = DynamicModInt;

fn solve<R: BufRead, W: Write>(scan: &mut Scanner<R>, out: &mut W) {
    let n: usize = scan.next();
    M::set_modulus(scan.next());

    let mut dp = vec![M::zero(); n + 1];
    dp[1] = M::one();
    let mut sum = M::one();
    for i in 2..=n {
        let root = (i as f64).sqrt() as usize;
        for j in 2..=root {
            let delta = dp[i / j];
            dp[i] += delta;
        }
        // i = 2 root = 1
        // high = 2
        // low = 2
        for k in 1..=root {
            let high = i / k;
            let low = max(2, max(root + 1, i / (k + 1) + 1));
            if low <= high {
                assert_eq!(i / low, k);
                assert_eq!(i / high, k);
                let delta = dp[k] * M::from(high - low + 1);
                dp[i] += delta;
            }
        }

        dp[i] += sum;
        sum += dp[i];
    }
    writeln!(out, "{}", dp[n]).ok();
}

fn main() {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = BufWriter::new(stdout.lock());

    let tests = 1; // scan.next::<usize>();
    for _ in 0..tests {
        solve(&mut scan, &mut out);
    }
}

