use std::fmt;
use std::iter::{Product, Sum};
use std::ops::*;

#[derive(Clone, Copy, Eq, PartialEq, Debug, Hash)]
pub struct DynamicModInt(pub i32);

impl Default for DynamicModInt {
    fn default() -> Self {
        DynamicModInt(0)
    }
}

impl fmt::Display for DynamicModInt {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl DynamicModInt {
    pub fn set_modulus(modulus: i32) {
        *Self::modulus_ref() = modulus;
    }

    pub fn modulus() -> i32 {
        *Self::modulus_ref()
    }

    fn modulus_ref() -> &'static mut i32 {
        static mut MODULES: i32 = 0;
        return unsafe { &mut MODULES };
    }

    pub fn raw(val: i32) -> Self {
        DynamicModInt(val)
    }

    #[inline]
    fn canon(val: i32) -> Self {
        DynamicModInt(if val < 0 { val + Self::modulus() } else { val })
    }

    #[inline]
    pub fn zero() -> Self {
        DynamicModInt(0)
    }

    #[inline]
    pub fn one() -> Self {
        DynamicModInt(1)
    }

    #[inline]
    pub fn two() -> Self {
        DynamicModInt(2)
    }

    pub fn pow(self, n: u64) -> Self {
        let mut n = n;
        let mut res = Self::one();
        let mut a = self;
        while n > 0 {
            if n & 1 == 1 {
                res = res * a;
            }
            a = a * a;
            n >>= 1;
        }

        res
    }

    pub fn inv(self) -> Self {
        self.pow(Self::modulus() as u64 - 2)
    }
}

macro_rules! from_bigger_int {
    ($($int:ident)*) => {$(
        impl From<$int> for DynamicModInt {
            fn from(val: $int) -> Self {
                Self::canon((val % Self::modulus() as $int) as i32)
            }
        }
    )*};
}
from_bigger_int!(u32 usize i64 u64 i128 u128);

macro_rules! from_smaller_int {
    ($($int: ident)*) => {$(
        impl From<$int> for DynamicModInt {
            fn from(val: $int) -> Self {
                Self::canon(val as i32 % Self::modulus())
            }
        }
    )*}
}
