impl Neg for DynamicModInt {
    type Output = Self;
    fn neg(self) -> Self {
        DynamicModInt(if self.0 == 0 {
            0
        } else {
            Self::modulus() - self.0
        })
    }
}

impl Add for DynamicModInt {
    type Output = Self;
    fn add(self, other: Self) -> Self {
        let s = self.0 + other.0;
        let m = Self::modulus();
        DynamicModInt(if s >= m { s - m } else { s })
    }
}

impl Sub for DynamicModInt {
    type Output = Self;
    fn sub(self, other: Self) -> Self {
        Self::canon(self.0 - other.0)
    }
}

impl Mul for DynamicModInt {
    type Output = Self;
    fn mul(self, other: Self) -> Self {
        let mul: u64 = (self.0 as u64 * other.0 as u64) % Self::modulus() as u64;
        DynamicModInt(mul as i32)
    }
}

impl Div for DynamicModInt {
    type Output = Self;
    fn div(self, other: Self) -> Self {
        self * other.inv()
    }
}

impl AddAssign for DynamicModInt {
    fn add_assign(&mut self, other: Self) {
        *self = *self + other;
    }
}

impl SubAssign for DynamicModInt {
    fn sub_assign(&mut self, other: Self) {
        *self = *self - other;
    }
}

impl MulAssign for DynamicModInt {
    fn mul_assign(&mut self, other: Self) {
        *self = *self * other;
    }
}

impl DivAssign for DynamicModInt {
    fn div_assign(&mut self, other: Self) {
        *self = *self / other;
    }
}

impl Sum for DynamicModInt {
    fn sum<I: Iterator<Item = Self>>(iter: I) -> Self {
        iter.fold(Self::zero(), Add::add)
    }
}

impl Product for DynamicModInt {
    fn product<I: Iterator<Item = Self>>(iter: I) -> Self {
        iter.fold(Self::one(), Mul::mul)
    }
}
