const MODULO: i32 = 1_000_000_007;
fn solve() -> Option<i64> {
    let n = read!();
    let k = read!();
    if k == 0 {
        return Some(1);
    }
    if n == 1 {
        let ans = nums::pow_mod(2, k, MODULO);
        return Some(ans as i64);
    }
    let free_select_01 = nums::pow_mod(2, n, MODULO);
    let mut factorial = vec![1i64; n as usize + 1];
    for i in 1usize..=(n as usize) {
        factorial[i] = factorial[i - 1] * i as i64;
        factorial[i] %= MODULO as i64;
    }
    let mut greater_or_equal_select_01: i64 = 0;
    for selected_1 in (0..=n as usize).step_by(2) {
        let a = factorial[n as usize];
        let b = factorial[n as usize - selected_1];
        let b = nums::pow_mod(b as i32, MODULO as u32 - 2, MODULO);
        let b2 = factorial[selected_1];
        let b2 = nums::pow_mod(b2 as i32, MODULO as u32 - 2, MODULO);
        let c = a * b as i64 % MODULO as i64 * b2 as i64 % MODULO as i64;
        greater_or_equal_select_01 += c as i64;
        greater_or_equal_select_01 %= MODULO as i64;
    }
    if n % 2 != 0 {
        greater_or_equal_select_01 += 1;
        greater_or_equal_select_01 %= MODULO as i64;
    }
    let mut answer: i64 = greater_or_equal_select_01 as i64;
    let mut prev: i64 = 0;
    let mut pow_bit = 1 as i64;
    for bit in 1..k {
        prev = answer;
        answer = 0;
        let x = greater_or_equal_select_01 as i64 * prev % MODULO as i64;
        answer += x as i64;
        answer %= MODULO as i64;
        if n % 2 == 0 {
            pow_bit *= free_select_01 as i64;
            pow_bit %= MODULO as i64;
            answer += pow_bit;
            answer -= prev;
            answer %= MODULO as i64;
        }
    }
    Some(answer)
}
fn calc(
    n: u32,
    bit: u32,
    free_select_01: i32,
    greater_or_equal_select_01: i32,
    modulo: i32,
) -> i64 {
    let mut answer: i64 = 0;
    if bit == 0 {
        return greater_or_equal_select_01 as i64;
    }
    if n % 2 == 0 {
        answer += nums::pow_mod(free_select_01, bit, modulo) as i64;
    }
    let x = greater_or_equal_select_01 as i64
        * calc(
            n,
            bit - 1,
            free_select_01,
            greater_or_equal_select_01,
            modulo,
        )
        % MODULO as i64;
    answer += x as i64;
    answer %= MODULO as i64;
    answer
}
