use std::io::{self, prelude::*};

fn solve<B: BufRead, W: Write>(scn: &mut Scanner<B>, wrt: &mut W) {
    let MOD: u64 = 1000000000+7;

    let N = scn.token::<u64>();
    let K = scn.token();

    let pw = |b: u64, mut a: u64| {
        let mut res = 1;
        let mut p = b;
        while a > 0 {
            if a & 1 == 1 {
                res = (res * p) % MOD;
            }
            p = (p*p) % MOD;
            a >>= 1;
        }
        res
    };

    let mut ans = 0;
    let mut dw = 1;

    for i in 0..K {
        if N & 1 == 0 {
            //auto win here and n even
            ans = (ans + ((dw * pw(2, K-i-1)) % MOD)) % MOD;
            dw = (dw * (pw(2, N-1) - 1)) % MOD;
        } else {
            //n odd
            dw = ((dw * (pw(2, N-1) + 1)) % MOD) % MOD;
        }
    }

    ans = (ans + dw) % MOD;

    writeln!(wrt, "{}", ans).unwrap();
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut reader = Scanner::new(stdin.lock());
    let mut writer = io::BufWriter::new(stdout.lock());

    let T = reader.token::<usize>();
    //let T = 1;
    for _ in 0..T {
        solve(&mut reader, &mut writer);
    }
}

pub struct Scanner<B> {
    reader: B,
    buf_str: Vec<u8>,
    buf_iter: std::str::SplitWhitespace<'static>,
}

impl<B: BufRead> Scanner<B> {
    pub fn new(reader: B) -> Self {
        Self {
            reader,
            buf_str: Vec::new(),
            buf_iter: "".split_whitespace(),
        }
    }
    pub fn token<T: std::str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buf_iter.next() {
                return token.parse().ok().expect("Failed parse");
            }
            self.buf_str.clear();
            self.reader
                .read_until(b'\n', &mut self.buf_str)
                .expect("Failed read");
            self.buf_iter = unsafe {
                let slice = std::str::from_utf8_unchecked(&self.buf_str);
                std::mem::transmute(slice.split_whitespace())
            }
        }
    }
}

