use modint::ModInt1000000007 as mint;
use modint::*;

pub struct Combination {
    fact: Vec<mint>,
    ifact: Vec<mint>,
}
impl Combination {
    pub fn new(n: i32) -> Self {
        let mut fact = vec![mint::new(0); (n + 1) as usize];
        let mut ifact = vec![mint::new(0); (n + 1) as usize];
        fact[0] = mint::new(1);
        for i in 1..n + 1 {
            fact[i as usize] = fact[(i - 1) as usize] * mint::new(i as i64)
        }
        ifact[n as usize] = fact[n as usize].inv();
        for i in (1..n + 1).rev() {
            ifact[(i - 1) as usize] = ifact[i as usize] * mint::new(i as i64)
        }
        let a = Combination {
            fact: fact,
            ifact: ifact,
        };
        return a;
    }
    #[macro_use]
    pub fn gen(&mut self, n: i32, k: i32) -> mint {
        if (k < 0 || k > n) {
            return mint::new(0 as i64);
        };
        return self.fact[n as usize] * self.ifact[k as usize] * self.ifact[(n - k) as usize];
    }
    pub fn P(&mut self, n: i32, k: i32) -> mint {
        self.fact[n as usize] * self.ifact[(n - k) as usize]
    }
}

fn main() {
    let T = get!(usize);
    let mut cmb = Combination::new(2 * 100000 + 10);

    for testcase in 0..T {
        mydbg!(testcase);
        let mut ans: mint = mint::new(0);
