            if k > N {
                break;
            }
            E += cmb.gen(N as i32, k as i32);
        }

        mydbg!(E);

        let mut dp = vec![vec![mint::new(0); 3]; K + 1];
        dp[0][0] = mint::new(1);
        for i in 0..K {
            for j in 0..2 {
                if dp[i][j] == mint::new(0) {
