use std::io::{self, BufWriter, Write};

mod scanner {
    use std::{io, str};
    /* https://github.com/EbTech/rust-algorithms */

    /// Same API as Scanner but nearly twice as fast, using horribly unsafe dark arts
    /// **REQUIRES** Rust 1.34 or higher
    pub struct UnsafeScanner<R> {
        reader: R,
        buf_str: Vec<u8>,
        buf_iter: str::SplitAsciiWhitespace<'static>,
    }

    impl<R: io::BufRead> UnsafeScanner<R> {
        pub fn new(reader: R) -> Self {
            Self {
                reader,
                buf_str: Vec::new(),
                buf_iter: "".split_ascii_whitespace(),
            }
        }

        /// This function should be marked unsafe, but noone has time for that in a
        /// programming contest. Use at your own risk!
        pub fn token<T: str::FromStr>(&mut self) -> T {
            loop {
                if let Some(token) = self.buf_iter.next() {
                    return token.parse().ok().expect("Failed parse");
                }
                self.buf_str.clear();
                self.reader
                    .read_until(b'\n', &mut self.buf_str)
                    .expect("Failed read");
                self.buf_iter = unsafe {
                    let slice = str::from_utf8_unchecked(&self.buf_str);
                    std::mem::transmute(slice.split_ascii_whitespace())
                }
            }
        }
    }
}

use std::cmp::{min, max};

fn s2vec(s: String) -> Vec<char> {
    s.chars().collect()
}

const MOD: i64 = 1000000007;

fn pow_mod(a: i64, x: i64) -> i64 {
    let (mut a_t, mut x_t, mut r) = (a, x, 1);
    while x_t > 0 {
        if x_t % 2 == 1 {
            r *= a_t;
            r %= MOD;
        }
        a_t *= a_t;
        a_t %= MOD;
        x_t /= 2;
    }
    r
}

fn main() {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let (mut scan, mut sout) = (
        scanner::UnsafeScanner::new(stdin.lock()),
        BufWriter::new(stdout.lock()),
    );
    let t: usize = scan.token();
    for _case in 0..t {
        let (n, k): (usize, usize) = (scan.token(), scan.token());
        if k > 0 {
        let mut dp: Vec<Vec<i64>> = vec![vec![0;2];k+1];
        dp[1][0] = pow_mod(2, (n-1) as i64) - if n % 2 == 0 { 1 } else { 0 };
        dp[1][1] = 1;
        for i in 2..=k {
            dp[i][0] = (((dp[i-1][0] + dp[i-1][1])%MOD)*(pow_mod(2, (n-1) as i64) - if n % 2 == 0 { 1 } else { 0 }))%MOD;
            if n % 2 == 0 {
                dp[i][1] = pow_mod(2, (n as i64)*((i-1) as i64));
            } else {
                dp[i][1] = dp[i-1][1];
            }
        }
        writeln!(sout, "{}", (dp[k][0] + dp[k][1])%MOD).ok();
        } else {
            writeln!(sout, "1").ok();
        }
    }
}

