use modint::*;
type M = ModInt<StaticMod>;

// ---------- begin input macro ----------
// reference: https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
    ($($r:tt)*) => {
        let s = {
            use std::io::Read;
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).unwrap();
            s
        };
        let mut iter = s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};
    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };
    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };
    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };
    ($iter:expr, bytes) => {
        read_value!($iter, String).bytes().collect::<Vec<u8>>()
    };
    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };
    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}
// ---------- end input macro ----------

fn run() {
    input! {
        n: usize,
        m: u32,
    }
    StaticMod::set_modulo(m);
    let pc = precalc::Precalc::new(n);
    let mut pow = vec![M::one(); n + 1];
    let two = M::new(2);
    for i in 1..=n {
        pow[i] = pow[i - 1] * two;
    }
    // dp[a][b]: 最後の空白がa, b個置いた
    let mut dp = vec![vec![M::zero(); n + 2]; n + 2];
    dp[0][0] = M::one();
    for i in 0..=(n + 1) {
        for j in 0..=i {
            let way = dp[i][j];
            if way.is_zero() {
                continue;
            }
            for k in 1..=(n - i) {
                dp[i + k + 1][j + k] += pow[k - 1] * way * pc.comb(j + k, j);
            }
        }
    }
    let mut ans = M::zero();
    for dp in dp[n + 1].iter() {
        ans += *dp;
    }
    println!("{}", ans);
}

fn main() {
    run();
}

