fn solve() {
    let (N, M, mut k) = get!(usize, usize, usize);
    let mut map = vec![vec!['!'; M]; N];

    for j in 0..M {
        if j % 2 == 1 || j + 1 >= M {
            continue;
        }

        for i in (0..N).rev() {
            let c = N - i - 1;
            if c % 2 == 0 {
                for l in 0..min(i + 1, k) {
                    map[l][j] = '0';
                    map[l][j + 1] = '0';
                }
                k -= min(i + 1, k);
            }
        }
    }

    for i in 0..N {
        for j in 0..M {
            if i + 1 < N && map[i][j] == '!' && map[i + 1][j] == '!' {
                map[i][j] = '1';
                map[i + 1][j] = '1';
            }
        }
    }

    if k == 0 {
        for i in 0..N {
            for j in 0..M {
                if map[i][j] == '!' {
                    echo!("NO");
                    return;
                }
            }
        }
        echo!("YES");
    } else {
        echo!("NO");
    }
}

fn main() {
    let T = get!(usize);
    for testcase in 0..T {
        mydbg!(testcase);
        let mut ans: u64 = 0;
        solve();
    }
}

use std::{io, io::prelude::*, str};

struct Scanner<R> {
    reader: R,
    buffer: Vec<String>,
}
impl<R: io::BufRead> Scanner<R> {
    fn new(reader: R) -> Self {
        Self {
            reader,
            buffer: vec![],
        }
    }

    fn t<T: str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            self.reader.read_line(&mut input).expect("Failed read");
            self.buffer = input.split_whitespace().rev().map(String::from).collect();
        }
    }
}

fn check(mut n: usize, mut m: usize, mut k: usize) -> bool {
    m /= 2;
    if m == 0 {
        return k == 0;
    }

    if n % 2 == 1 {
        if k < m {
            return false;
        }
        k -= m;
        n -= 1;
    }
    if k % 2 == 1 {
        return false;
    }

    let mut rows = 0usize;
    while k >= m * 2 {
        k -= m * 2;
        rows += 2;
    }
    if n < rows {
        return false;
    }

    n -= rows;
    k / 2 <= n
}

fn main() {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = io::BufWriter::new(stdout);

    let tn: usize = scan.t();
    for _ in 0..tn {
        let (n, m, k): (usize, usize, usize) = (scan.t(), scan.t(), scan.t());

        let ok = check(n, m, k);
        if ok {
            writeln!(out, "YES").ok();
        } else {
            writeln!(out, "NO").ok();
        }
    }
}

