type Map<K, V> = BTreeMap<K, V>;
type Set<T> = BTreeSet<T>;
type Deque<T> = VecDeque<T>;

fn run() {
    input! {
        t: usize,
        ask: [(usize, usize, usize); t],
    }
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    for (h, w, k) in ask {
        let b = k;
        let a = h * w / 2 - b;
        let ans = match (h % 2, w % 2, a % 2, b % 2) {
            (0, 0, 0, 0) => "YES",
            (0, 0, _, _) => "NO",
            (0, 1, _, 0) => "YES",
            (0, 1, _, _) => "NO",
            (1, 0, 0, _) => "YES",
            _ => "NO",
        };
        writeln!(out, "{}", ans).ok();
    }
}

fn main() {
    run();
}

