fn run() {
    input! {
        s: bytes,
    }
    let mut x = 1;
    if s.contains(&b'X') {
        x = 10;
    }
    let mut ans = 0;
    for v in 0..x {
        let mut s = s.clone();
        s.iter_mut().for_each(|s| {
            if *s == b'X' {
                *s = b'0' + v as u8;
            }
        });
        if s[0] == b'0' && s.len() > 1 {
            continue;
        }
        let mut dp = [0; 25];
        dp[0] = 1u64;
