type M = DynamicModInt;

fn solve<R: BufRead, W: Write>(sc: &mut Scanner<R>, out: &mut W) {
    let n: usize = sc.next();
    let mx: usize = sc.next();
    let comb = Comb::<M>::new(n);

    let mut dp = vec![vec![M::zero(); mx + 1]; n + 1];
    dp[1][1..=mx].iter_mut().for_each(|v| *v = M::one());
    let mut p = vec![vec![M::zero(); n]; n];
    for i in 0..n {
        for j in 0..n {
            p[i][j] = M::from(i).pow(j as u64);
        }
    }
    for i in 1..=n {
        for m in 1..=mx {
            let delta = dp[i][m];
            if delta.0 == 0 {
                continue;
            }
            let mut nm = m + i - 1;
            for k in (0..=n - i).take_while(move |_| nm <= mx) {
                dp[i + k][nm] += delta * comb.choose(i + k, i) * p[i + k - 1][k];
                nm += 1;
            }
        }
    }
    let ans = M::from(mx).pow(n as u64) - dp[n].iter().cloned().sum::<M>();
    writeln!(out, "{}", ans).ok();
}

