use std::fmt;
use std::iter::{Product, Sum};
use std::ops::*;

#[derive(Clone, Copy, Eq, PartialEq, Debug, Hash)]
pub struct DynamicModInt(pub i32);

impl Default for DynamicModInt {
    fn default() -> Self {
        DynamicModInt(0)
    }
}

impl fmt::Display for DynamicModInt {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl DynamicModInt {
    pub fn set_modulus(modulus: i32) {
        *Self::modulus_ref() = modulus;
    }

    pub fn modulus() -> i32 {
        *Self::modulus_ref()
    }

    fn modulus_ref() -> &'static mut i32 {
        static mut MODULUS: i32 = 1;
        unsafe { &mut MODULUS }
    }

    pub fn raw(val: i32) -> Self {
        DynamicModInt(val)
    }

    #[inline]
    fn canon(val: i32) -> Self {
        DynamicModInt(if val < 0 { val + Self::modulus() } else { val })
    }

    #[inline]
    pub fn zero() -> Self {
        DynamicModInt(0)
    }

    #[inline]
    pub fn one() -> Self {
        DynamicModInt(1)
    }

    #[inline]
    pub fn two() -> Self {
        DynamicModInt(2)
    }

    pub fn pow(self, n: u64) -> Self {
        let mut n = n;
        let mut res = Self::one();
        let mut a = self;
        while n > 0 {
            if n & 1 == 1 {
                res *= a;
            }
            a *= a;
            n >>= 1;
        }

        res
    }

    pub fn inv(self) -> Self {
        self.pow(Self::modulus() as u64 - 2)
    }
}

macro_rules! from_bigger_int {
    ($($int:ident)*) => {$(
        impl From<$int> for DynamicModInt {
            fn from(val: $int) -> Self {
                Self::canon((val % Self::modulus() as $int) as i32)
            }
        }
    )*};
}
from_bigger_int!(u32 usize i64 u64 i128 u128);

macro_rules! from_smaller_int {
    ($($int: ident)*) => {$(
        impl From<$int> for DynamicModInt {
            fn from(val: $int) -> Self {
                Self::canon(val as i32 % Self::modulus())
            }
        }
    )*}
}
from_smaller_int!(i32 i16 u16 i8 u8);

impl Neg for DynamicModInt {
    type Output = Self;
    fn neg(self) -> Self {
        DynamicModInt(if self.0 == 0 {
            0
        } else {
            Self::modulus() - self.0
        })
    }
}

impl Add for DynamicModInt {
    type Output = Self;
    fn add(self, other: Self) -> Self {
        let s = self.0 + other.0;
        let m = Self::modulus();
        DynamicModInt(if s >= m { s - m } else { s })
    }
}

impl Sub for DynamicModInt {
    type Output = Self;
    fn sub(self, other: Self) -> Self {
        Self::canon(self.0 - other.0)
    }
}

impl Mul for DynamicModInt {
    type Output = Self;
    fn mul(self, other: Self) -> Self {
        let mul: u64 = (self.0 as u64 * other.0 as u64) % Self::modulus() as u64;
        DynamicModInt(mul as i32)
    }
}

impl Div for DynamicModInt {
    type Output = Self;
    #[allow(clippy::suspicious_arithmetic_impl)]
    fn div(self, other: Self) -> Self {
        self * other.inv()
    }
}

impl AddAssign for DynamicModInt {
    fn add_assign(&mut self, other: Self) {
        *self = *self + other;
    }
}

impl SubAssign for DynamicModInt {
    fn sub_assign(&mut self, other: Self) {
        *self = *self - other;
    }
}

impl MulAssign for DynamicModInt {
    fn mul_assign(&mut self, other: Self) {
        *self = *self * other;
    }
}

impl DivAssign for DynamicModInt {
    fn div_assign(&mut self, other: Self) {
        *self = *self / other;
    }
}

impl Sum for DynamicModInt {
    fn sum<I: Iterator<Item = Self>>(iter: I) -> Self {
        iter.fold(Self::zero(), Add::add)
    }
}

impl Product for DynamicModInt {
    fn product<I: Iterator<Item = Self>>(iter: I) -> Self {
        iter.fold(Self::one(), Mul::mul)
    }
}
