use std::ops::{Add, Div, Mul};

pub struct Comb<F> {
    fac: Vec<F>,
    inv_fac: Vec<F>,
}

impl<F: Copy + From<usize> + Eq + Add + Mul<Output = F> + Div<Output = F>> Comb<F> {
    pub fn new(maxn: usize) -> Self {
        let one = F::from(1);
        let mut fac = vec![one; maxn + 1];
        for i in 1..=maxn {
            fac[i] = fac[i - 1] * F::from(i);
        }
        let mut inv_fac = vec![one; maxn + 1];
        inv_fac[maxn] = one / fac[maxn];
        assert!(fac[maxn] * inv_fac[maxn] == one);
        for i in (1..maxn).rev() {
            inv_fac[i] = inv_fac[i + 1] * F::from(i + 1);
        }
        Comb { fac, inv_fac }
    }

    pub fn choose(&self, n: usize, k: usize) -> F {
        if k > n {
            F::from(0)
        } else {
            self.fac[n] * self.inv_fac[k] * self.inv_fac[n - k]
        }
    }

    pub fn fac(&self, n: usize) -> F {
        self.fac[n]
    }

    pub fn inv_fac(&self, n: usize) -> F {
        self.inv_fac[n]
    }
}
