const MOD: i64 = 998244353;

fn pow_mod(a: i64, x: i64) -> i64 {
    let mut r = 1;
    let mut a_t = a;
    let mut x_t = x;
    while x_t != 0 {
        if x_t % 2 == 1 {
            r *= a_t;
            r %= MOD;
        }
        a_t *= a_t;
        a_t %= MOD;
        x_t /= 2;
    }
    r
}

const MAX: usize = 501;

fn main() {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let (mut scan, mut sout) = (
        scanner::UnsafeScanner::new(stdin.lock()),
        BufWriter::new(stdout.lock()),
    );
    let n: usize = scan.token();
    let x: usize = scan.token();
    let mut dp: Vec<Vec<i64>> = vec![vec![0;MAX];n+1];
    let mut binom: Vec<Vec<i64>> = vec![vec![0;MAX+1];MAX+1];
    binom[0][0] = 1;
    for i in 1..=MAX {
        binom[i][0] = 1;
        binom[i][i] = 1;
        for j in 1..i {
            binom[i][j] += binom[i-1][j-1];
            binom[i][j] %= MOD;
            binom[i][j] += binom[i-1][j];
            binom[i][j] %= MOD;
        }
    }
    dp[n][0] = 1;
    for r in (1..=n).rev() {
        for lx in 0..=x {
            for y in 0..=(n-r) {
                if lx >= y+r-1 {
                    let d = max(0, min(x-lx+(y+r-1), y+r-1));
                    dp[r][lx] += (((dp[r+y][lx-(y+r-1)]*binom[y+r][y])%MOD)*pow_mod(d as i64, y as i64))%MOD;
                    dp[r][lx] %= MOD;
                }
            }
        }
    }
    let mut all = pow_mod(x as i64, n as i64);
    for lx in 0..=x {
        all -= (dp[1][lx]*((x - lx) as i64))%MOD;
        all += MOD;
        all %= MOD;
    }
    writeln!(sout, "{}", all).ok();
}

