			let mut res = Z0;
			for k in 1..=j {
				res += dp[i-j+1][k] * Z::new((j-1) as i32).pow((j-k) as i32) * cnr(j-1,k-1);
			}
			dp[i][j] = res;
		}
		s += dp[i][n];
	}
	s *= Z::new(n as i32);
	let ans = Z::new(x as i32).pow(n as i32) - s;
	writeln!(rout, "{}", ans).unwrap();
}

